// SeedChooserScreen::PickFromWeightedArrayUsingSpecialRandSeed(TodWeightedArray const*,int,Sexy::MTRand &)
// @0014C204  92 bytes
// ==========================================================================
int SeedChooserScreen::PickFromWeightedArrayUsingSpecialRandSeed(TodWeightedArray const* theArray, int theCount, Sexy::MTRand &theRand)
{
  if (theCount <= 0)
    return theRand.Next(0u);

  unsigned int aTotalWeight = 0;
  for (int i = 0; i < theCount; ++i)
    aTotalWeight += theArray[i].mWeight;

  const unsigned int aRoll = theRand.Next(aTotalWeight);

  unsigned int aWeightSoFar = theArray[0].mWeight;
  if (aWeightSoFar > aRoll)
    return theArray[0].mItem;

  for (int i = 1; i < theCount; ++i)
  {
    aWeightSoFar += theArray[i].mWeight;
    if (aWeightSoFar > aRoll)
      return theArray[i].mItem;
  }
  return aRoll;
}

