int SeedChooserScreen::PickSeedsFromLevelConfig()
{
  // The level's seed list already names the packets this level hands out for
  // free; they are placed straight into the bank, skipping any slot the level's
  // seed-bank limit has already used up.
  Sexy::Level &aLevel = mApp->mLevel;
  int aSeedIndex = 0;
  for (size_t aConfig = 0; aConfig < aLevel.mSeedConfig.size(); ++aConfig)
  {
    if (aLevel.mSeedBankLimit > 0 && aLevel.mSeedBankLimit <= aSeedIndex)
      continue;
    if (mBoard->mSeedBank[0]->mNumPackets <= aSeedIndex)
      continue;

    const SeedType aSeedType = (SeedType)aLevel.mSeedConfig[aConfig];
    const int aPacketX = mBoard->GetSeedPacketPositionX(aSeedIndex, 0, false);

    ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedType];
    aChosenSeed.mX = aPacketX;
    aChosenSeed.mY = 8;
    aChosenSeed.mStartX = aPacketX;
    aChosenSeed.mStartY = 8;
    aChosenSeed.mEndX = aPacketX;
    aChosenSeed.mEndY = 8;
    aChosenSeed.mSeedState = SEED_IN_BANK;
    aChosenSeed.mSeedIndexInBank = aSeedIndex++;
    aChosenSeed.mCrazyDavePicked = true;
    ++mSeedsInBank;
  }
  return 0;
}

