// ==========================================================================
// SeedChooserScreen::GetSeedPositionInBank(int,int &,int &,int)
// @0014C4BC  226 bytes
// ==========================================================================
int SeedChooserScreen::GetSeedPositionInBank(int theIndex, int & theX, int & theY, int thePlayerIndex)
{
  const bool aIsCoop = mApp->IsCoopMode();
  // In co-op, player 2 draws from the second bank.
  SeedBank *aSeedBank = (aIsCoop && thePlayerIndex != 0) ? mSeedBank2 : mSeedBank1;

  // The zombie chooser always lays its packets out as the second player's row.
  const int aPlayerIndex = mIsZombieChooser ? 1 : (aIsCoop ? (thePlayerIndex != 0) : 0);

  // When the first player's chooser is still up next to the zombie chooser, the
  // 1P packets are squeezed left to leave room.
  const bool aShiftForOtherChooser =
      mIsZombieChooser || (mApp->mSeedChooserScreen != nullptr && mApp->mSeedChooserScreen != this);

  // VS mode packs the bank slightly tighter so both rows fit on the TV screen.
  const float aVSScale = (mApp->mGameMode == GAMEMODE_MP_VS) ? 0.9f : 1.0f;

  const int aPacketX = mBoard->GetSeedPacketPositionX(theIndex, aPlayerIndex, aShiftForOtherChooser);
  const int aResult = (int)((float)aPacketX * aVSScale);

  theX = aSeedBank->mX + aResult - mX;
  theY = aSeedBank->mY + 8 - mY;
  if (mApp->mGameMode == GAMEMODE_MP_VS)
    theY -= 4;
  return aResult;
}

// ==========================================================================
// SeedChooserScreen::SeedNotAllowedToPick(SeedType)
// @0014C5A4  94 bytes
