int SeedChooserScreen::SeedNotAllowedToPick(SeedType theSeedType)
{
  // Two modes ban a fixed handful of packets on top of the level's own list.
  const GameMode aGameMode = mApp->mGameMode;
  if (aGameMode == GAMEMODE_CHALLENGE_LAST_STAND)
  {
    if (theSeedType == SEED_SUNFLOWER || theSeedType == SEED_SEASHROOM || theSeedType == SEED_TWINSUNFLOWER)
      return 1;
    if (theSeedType == SEED_PUFFSHROOM || theSeedType == SEED_SUNSHROOM)
      return 1;
  }
  else if (aGameMode == GAMEMODE_MP_VS)
  {
    // TANGLEKELP and BLOVER differ only in bit 3.
    if (theSeedType == SEED_TANGLEKELP || theSeedType == SEED_BLOVER || theSeedType == SEED_LILYPAD)
      return 1;
    if (theSeedType == SEED_SEASHROOM || theSeedType == SEED_PLANTERN || theSeedType == SEED_FLOWERPOT || theSeedType == SEED_MARIGOLD)
      return 1;
  }
  return mApp->mLevel.isCardNotAllowedToPick(theSeedType);
}

