// ==========================================================================
// SeedChooserScreen::VSAutoPickResourceGen()
// @0014C698  132 bytes
// ==========================================================================
int SeedChooserScreen::VSAutoPickResourceGen()
{
  // VS mode's resource generator is granted one free packet at the front of the
  // bank, but only while the player has not picked anything yet.
  if (mSeedsInBank != 0)
    return 0;

  const SeedType aSeedType = mIsZombieChooser ? SEED_ZOMBIE_GRAVESTONE : SEED_SUNFLOWER;
  const int aPlayerIndex = mIsZombieChooser ? 1 : 0;

  int aX = 0;
  int aY = 0;
  GetSeedPositionInBank(0, aX, aY, 0);

  ChosenSeedData &aChosenSeed = mChosenSeeds[GetSeedPacketIndex(aSeedType)];
  aChosenSeed.mX = aX;
  aChosenSeed.mY = aY;
  aChosenSeed.mStartX = aX;
  aChosenSeed.mStartY = aY;
  aChosenSeed.mEndX = aX;
  aChosenSeed.mEndY = aY;
  aChosenSeed.mChosenPlayerIndex = aPlayerIndex;
  aChosenSeed.mSeedState = SEED_IN_BANK;
  aChosenSeed.mSeedIndexInBank = 0;
  aChosenSeed.mCrazyDavePicked = true;

  ++mSeedsInBank;
  ++mSeedsIn1PBank;
  return 1;
}

// ==========================================================================
// SeedChooserScreen::DrawPacket(Sexy::Graphics *,int,int,int,int,float,int,Sexy::Color &,bool,bool)
// @0014C71C  156 bytes
// ==========================================================================
void SeedChooserScreen::DrawPacket(Sexy::Graphics * g, int theX, int theY, int theSeedType, int theImitaterType, float thePercentDark, int theGrayness, Color & theColor, bool theDrawCost, bool theUseCurrentCost)
{
  // The brightness offset is halved and pushed by the packet colour's own
  // average, so a darker packet gets less of it.
  const int aAverage = (theColor.GetRed() + theColor.GetGreen() + theColor.GetBlue()) / 3;
  DrawSeedPacket(
           g,
           (float)theX,
           (float)theY,
           (SeedType)theSeedType,
           (SeedType)theImitaterType,
           thePercentDark,
           (aAverage + theGrayness) / 2,
           theDrawCost,
           0,
           mIsZombieChooser,
           theUseCurrentCost);
}

// ==========================================================================
// SeedChooserScreen::UpdateViewLawn()
// @0014C7B8  402 bytes
// ==========================================================================
void SeedChooserScreen::UpdateViewLawn()
{
  if (mChooseState != CHOOSE_VIEW_LAWN)
    return;

  ++mViewLawnTime;

  if (mViewLawnTime == 100)
  {
    const Sexy::String aAdvice("[CLICK_TO_CONTINUE]");
    mBoard->DisplayAdviceAgain(aAdvice, MESSAGE_STYLE_HINT_STAY, AdviceType(63));
  }
  else if (mViewLawnTime == 251)
  {
    // Clamp so the "slide the lawn back in" phase starts from its own first frame.
    mViewLawnTime = 250;
    mBoard->Move(0, 0);
    Move(0, 720);
    return;
  }

  const int aBoardTargetX = 1180 - mApp->mWidth;
  if (mViewLawnTime <= 100)
  {
    // Slide the lawn in from the right and pull the chooser down with it.
    const int aBoardShift = TodAnimateCurve(0, 100, mViewLawnTime, aBoardTargetX, 0.0f, CURVE_EASE_IN_OUT);
    mBoard->Move(-aBoardShift, 0);

    const int aChooserTargetY = 720 - (IMAGE_SEEDCHOOSER_BACKGROUND)->mHeight;
    const int aChooserY = TodAnimateCurve(0, 40, mViewLawnTime, aChooserTargetY, 720.0f, CURVE_EASE_IN_OUT);
    Move(0, aChooserY);
    return;
  }

  if ((unsigned int)(mViewLawnTime - 101) <= 0x95)
  {
    // Fully in view: hold the lawn still.
    mBoard->Move(0, 0);
    Move(0, 720);
    return;
  }

  if ((unsigned int)(mViewLawnTime - 251) <= 0x63)
  {
    mBoard->ClearAdvice(AdviceType(63));
    const int aBoardShift = TodAnimateCurve(250, 350, mViewLawnTime, 0, (float)aBoardTargetX, CURVE_EASE_IN_OUT);
    mBoard->Move(-aBoardShift, 0);

    const int aChooserY = TodAnimateCurve(310, 350, mViewLawnTime, 720, 0.0f, CURVE_EASE_IN_OUT);
    Move(0, aChooserY);
  }
  else
  {
    mChooseState = CHOOSE_NORMAL;
    mViewLawnTime = 0;
  }
}

