// ==========================================================================
// SeedChooserScreen::FlyersAreComing()
// @0014C97C  72 bytes
// ==========================================================================
int SeedChooserScreen::FlyersAreComing()
{
  // Any balloon zombie in the level's wave table means the player needs a plant
  // that can shoot it down.
  const int aNumWaves = mBoard->mNumWaves;
  for (int aWave = 0; aWave < aNumWaves; ++aWave)
  {
    for (int aIndex = 0; aIndex < MAX_ZOMBIES_IN_WAVE; ++aIndex)
    {
      const ZombieType aZombieType = mBoard->mZombiesInWave[aWave][aIndex];
      if (aZombieType == ZOMBIE_INVALID)
        break;
      if (aZombieType == ZOMBIE_BALLOON)
        return 1;
    }
  }
  return 0;
}

// ==========================================================================
// SeedChooserScreen::FlyProtectionCurrentlyPlanted()
// @0014C9C4  46 bytes
// ==========================================================================
int SeedChooserScreen::FlyProtectionCurrentlyPlanted()
{
  // Walk the lawn looking for a plant that can hit airborne zombies.
  Plant *aPlant = nullptr;
  int aFound = 0;
  do
  {
    aFound = mBoard->IteratePlants(aPlant);
    if (aFound == 0)
      break;
  }
  while (aPlant->mSeedType != SEED_CATTAIL && aPlant->mSeedType != SEED_CACTUS);
  return aFound;
}

