// ==========================================================================
// SeedChooserScreen::RebuildHelpbar()
// @0014CA2C  316 bytes
// ==========================================================================
int SeedChooserScreen::RebuildHelpbar()
{
  HelpBarWidget *aHelpBar = mApp->mHelpBarWidget;
  aHelpBar->ClearButtons(0);

  // Upsell, VS and Tree of Wisdom run without the shop/almanac help buttons.
  const GameMode aGameMode = mApp->mGameMode;
  if ((aGameMode & ~4) != GAMEMODE_UPSELL && aGameMode != GAMEMODE_TREE_OF_WISDOM)
  {
    if (mApp->CanShowStore())
    {
      const Sexy::String aLabel("[SHOP_BUTTON]");
      aHelpBar->AddButton(GAMEPAD_BUTTON_X, aLabel, (HelpBarWidget::HelpAlign)1);
    }
    if (mApp->CanShowAlmanac())
    {
      const Sexy::String aLabel("[ALMANAC_BUTTON]");
      aHelpBar->AddButton(GAMEPAD_BUTTON_Y, aLabel, (HelpBarWidget::HelpAlign)1);
    }
    if (mBoard->mCutScene->IsSurvivalRepick())
    {
      const Sexy::String aLabel("[VIEW_LAWN]");
      aHelpBar->AddButton(GAMEPAD_BUTTON_SELECT, aLabel, (HelpBarWidget::HelpAlign)1);
    }
  }
  return mApp->ShowHelpBarWidget();
}

// ==========================================================================
// SeedChooserScreen::PickedPlantType(SeedType)
// @0014CB90  60 bytes
// ==========================================================================
int SeedChooserScreen::PickedPlantType(SeedType theSeedType)
{
  // An Imitater counts as the plant it is imitating.
  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    const ChosenSeedData &aChosenSeed = mChosenSeeds[i];
    if (aChosenSeed.mSeedState != SEED_IN_BANK)
      continue;
    if (aChosenSeed.mSeedType == theSeedType)
      return 1;
    if (aChosenSeed.mSeedType == SEED_IMITATER && aChosenSeed.mImitaterType == theSeedType)
      return 1;
  }
  return 0;
}

// ==========================================================================
// SeedChooserScreen::SeedNotRecommendedToPick(SeedType)
// @0014CBCC  36 bytes
// ==========================================================================
unsigned int SeedChooserScreen::SeedNotRecommendedToPick(SeedType theSeedType)
{
  unsigned int aRecFlags = (unsigned int)mBoard->SeedNotRecommendedForLevel(theSeedType);
  // Coffee Bean cancels the "useless at night" warning. Bit 0 is
  // NOT_RECOMMENDED_NOCTURNAL.
  if ((aRecFlags & 1) != 0 && PickedPlantType(SEED_INSTANT_COFFEE) != 0)
    aRecFlags &= ~1u;
  return aRecFlags;
}

// ==========================================================================
// SeedChooserScreen::CheckSeedUpgrade(SeedType,SeedType)
// @0014CE84  604 bytes
// ==========================================================================
int SeedChooserScreen::CheckSeedUpgrade(int theUpgradeTo, int theUpgradeFrom)
{
  // Survival levels never let a plant be swapped for its upgrade.
  if (mApp->IsSurvivalMode())
    return 1;

  // Only warn when the player already holds the base plant and not the upgrade.
  if (PickedPlantType((SeedType)theUpgradeTo) == 0 || PickedPlantType((SeedType)theUpgradeFrom) != 0)
    return 1;

  Sexy::String aWarning;
  TodStringTranslate(&aWarning, "[SEED_CHOOSER_UPGRADE_WARNING]");

  const Sexy::String aToName = Plant::GetNameString((SeedType)theUpgradeTo, (SeedType)-1);
  const Sexy::String aFromName = Plant::GetNameString((SeedType)theUpgradeFrom, (SeedType)-1);

  Sexy::String aReplaced;
  TodReplaceString(&aReplaced, &aWarning, "{UPGRADE_TO}", &aToName);
  aWarning = aReplaced;
  TodReplaceString(&aReplaced, &aWarning, "{UPGRADE_FROM}", &aFromName);
  aWarning = aReplaced;

  return DisplayRepickWarningDialog(aWarning.c_str()) ? 1 : 0;
}

// ==========================================================================
// SeedChooserScreen::HasPacket(int,bool)
// @0014D0F4  42 bytes
// ==========================================================================
int SeedChooserScreen::HasPacket(int theSeedType, bool theIsZombie)
{
  if (mApp->mGameMode != GAMEMODE_MP_VS)
    return mApp->HasSeedType((SeedType)theSeedType, theIsZombie) ? 1 : 0;

  // In VS mode the zombie chooser is always offered the gravestone packet,
  // whatever the profile has unlocked.
  if (mIsZombieChooser && theSeedType == SEED_ZOMBIE_GRAVESTONE)
    return 1;
  return mApp->HasSeedType((SeedType)theSeedType, theIsZombie) ? 1 : 0;
}

// ==========================================================================
// SeedChooserScreen::CrazyDavePickSeeds()
// @0014D120  350 bytes
// ==========================================================================
int SeedChooserScreen::CrazyDavePickSeeds()
{
  // Build the weighted candidate list: one entry per plant packet, with weight
  // 0 for anything the profile has not unlocked or the level forbids.
  TodWeightedArray aChoices[NUM_SEEDS_IN_CHOOSER];
  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    aChoices[i].mItem = i;

    const bool aUnusable = HasPacket(i, mIsZombieChooser) == 0
        || SeedNotRecommendedToPick((SeedType)i) != 0
        || SeedNotAllowedToPick((SeedType)i) != 0
        || Plant::IsUpgrade((SeedType)i);

    // Umbrella Leaf, Imitater and Blover are never handed out for free.
    const bool aExcluded = aUnusable || i == SEED_UMBRELLA || i == SEED_IMITATER || i == SEED_BLOVER;
    aChoices[i].mWeight = aExcluded ? 0 : 1;
  }

  // Umbrella Leaf answers a bungee or catapult wave; Blover answers balloons or
  // fog; Torchwood is pointless on the roof.
  if (mBoard->mZombieAllowed[ZOMBIE_BUNGEE] || mBoard->mZombieAllowed[ZOMBIE_CATAPULT])
    aChoices[SEED_UMBRELLA].mWeight = 1;
  if (mBoard->mZombieAllowed[ZOMBIE_BALLOON] || mBoard->StageHasFog())
    aChoices[SEED_BLOVER].mWeight = 1;
  if (mBoard->StageHasRoof())
    aChoices[SEED_TORCHWOOD].mWeight = 0;

  // Dave rolls his own generator, seeded from the level, so the free packets are
  // reproducible for a given level.
  MTRand aRand((unsigned long)mBoard->GetLevelRandSeed());

  int aBankIndex = 0;
  do
  {
    const int aSeedType = PickFromWeightedArrayUsingSpecialRandSeed(aChoices, NUM_SEEDS_IN_CHOOSER, aRand);
    aChoices[aSeedType].mWeight = 0;

    int aX = 0;
    int aY = 0;
    GetSeedPositionInBank(aBankIndex, aX, aY, 0);

    ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedType];
    aChosenSeed.mX = aX;
    aChosenSeed.mY = aY;
    aChosenSeed.mStartX = aX;
    aChosenSeed.mStartY = aY;
    aChosenSeed.mEndX = aX;
    aChosenSeed.mEndY = aY;
    aChosenSeed.mChosenPlayerIndex = 0;
    aChosenSeed.mSeedState = SEED_IN_BANK;
    aChosenSeed.mSeedIndexInBank = aBankIndex++;
    aChosenSeed.mCrazyDavePicked = true;

    ++mSeedsInBank;
    ++mSeedsIn1PBank;
  }
  while (aBankIndex != 3);

  return mSeedsInBank;
}

// ==========================================================================
// SeedChooserScreen::Has7Rows()
// @0014D280  152 bytes
// ==========================================================================
int SeedChooserScreen::Has7Rows()
{
  if (mApp->mGameMode == GAMEMODE_MP_VS)
    return 0;
  if (mApp->HasFinishedAdventure())
    return 1;

  // Before the adventure is over the chooser only grows to seven rows once the
  // late-game packets start showing up. (The binary tests packet 40 twice and
  // never tests 46; that duplication is reproduced as-is.)
  if (HasPacket(40, false) == 0
    && HasPacket(41, false) == 0
    && HasPacket(42, false) == 0
    && HasPacket(43, false) == 0
    && HasPacket(44, false) == 0
    && HasPacket(40, false) == 0
    && HasPacket(45, false) == 0
    && HasPacket(47, false) == 0)
  {
    return 0;
  }
  return 1;
}

// ==========================================================================
// SeedChooserScreen::GetSeedPositionInChooser(int,int &,int &)
// @0014D318  148 bytes
// ==========================================================================
int SeedChooserScreen::GetSeedPositionInChooser(int theIndex, int & theX, int & theY)
{
  // The Imitater button is a real widget, so it reports its own position.
  if (!mIsZombieChooser && theIndex == SEED_IMITATER)
  {
    theX = mImitaterButton->mX;
    theY = mImitaterButton->mY;
    return 0;
  }

  const int aRow = theIndex / NumColumns();
  const int aCol = theIndex % NumColumns();

  theX = 53 * aCol + 22;
  if (mIsZombieChooser && aRow == 3)
    theX = 53 * aCol + 48;

  if (Has7Rows() != 0)
    theY = 70 * aRow + 123;
  else
    theY = 73 * aRow + 128;
  return 0;
}

// ==========================================================================
// SeedChooserScreen::GetNextSeedInDir(int,SeedChooserScreen::SeedDir)
// @0014D3AC  224 bytes
// ==========================================================================
int SeedChooserScreen::GetNextSeedInDir(int theIndex, SeedDir theDirection)
{
  const int aNumColumns = NumColumns();

  int aRow;
  int aCol;
  if (theIndex == SEED_IMITATER)
  {
    // The Imitater button sits past the end of the packet grid.
    aRow = 5;
    aCol = 8;
  }
  else
  {
    aRow = theIndex / aNumColumns;
    aCol = theIndex % aNumColumns;
  }

  int aNumRows;
  if (mApp->mGameMode == GAMEMODE_MP_VS)
    aNumRows = 4;
  else if (Has7Rows() != 0)
    aNumRows = 5;
  else
    aNumRows = 4;

  if (mIsZombieChooser)
  {
    // Two corners of the zombie grid wrap back onto themselves.
    if (theIndex == 14 && theDirection == SEED_DIR_DOWN)
      return 18;
    if (theIndex == 18 && theDirection == SEED_DIR_RIGHT)
      return 18;
    aNumRows = 3;
  }

  switch (theDirection)
  {
    case SEED_DIR_UP:
      if (aRow > 0)
        --aRow;
      break;
    case SEED_DIR_DOWN:
      if (aRow < aNumRows)
        ++aRow;
      break;
    case SEED_DIR_LEFT:
      if (aCol > 0)
        --aCol;
      break;
    case SEED_DIR_RIGHT:
      if (aCol < aNumColumns - 1)
        ++aCol;
      break;
    default:
      break;
  }
  return aCol + NumColumns() * aRow;
}

// ==========================================================================
// SeedChooserScreen::SeedHitTest(int,int)
// @0014D48C  160 bytes
// ==========================================================================
int SeedChooserScreen::SeedHitTest(int theX, int theY)
{
  if (!mMouseVisible)
    return SEED_NONE;

  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    const SeedType aSeedType = mIsZombieChooser ? (SeedType)GetZombieSeedType(i) : (SeedType)i;
    ChosenSeedData &aChosenSeed = mChosenSeeds[i];
    if (HasPacket(aSeedType, mIsZombieChooser) == 0 || aChosenSeed.mSeedState == SEED_PACKET_HIDDEN)
      continue;

    // Packets are 49x69; hit either where the packet actually is or where its
    // home slot is, so a seed in flight is still clickable.
    if (theX >= aChosenSeed.mX && theY >= aChosenSeed.mY
        && theX <= aChosenSeed.mX + 49 && theY <= aChosenSeed.mY + 69)
      return aSeedType;

    int aX = 0;
    int aY = 0;
    GetSeedPositionInChooser(i, aX, aY);
    if (theX >= aX && theY >= aY && theX <= aX + 49 && theY <= aY + 69)
      return aSeedType;
  }
  return SEED_NONE;
}

// ==========================================================================
// SeedChooserScreen::UpdateCursor()
// @0014D52C  172 bytes
// ==========================================================================
int SeedChooserScreen::UpdateCursor()
{
  // No cursor work while a dialog is up, the shovel tutorial is running, or the
  // upsell screen owns the chooser.
  if (mApp->GetDialogCount() != 0)
    return 0;
  if (mBoard->mCutScene->IsInShovelTutorial())
    return 0;
  if (mApp->mGameMode == GAMEMODE_UPSELL)
    return 0;

  int aSeedType = SeedHitTest(mCursorPositionX1, mCursorPositionY1);
  if (aSeedType != SEED_NONE)
  {
    // A packet Crazy Dave handed out is not clickable.
    const ChosenSeedData &aChosenSeed = mChosenSeeds[GetSeedPacketIndex((SeedType)aSeedType)];
    if (aChosenSeed.mSeedState == SEED_IN_BANK && aChosenSeed.mCrazyDavePicked)
      aSeedType = SEED_NONE;
  }

  if (mMouseVisible && mChooseState != CHOOSE_VIEW_LAWN)
  {
    if (aSeedType == SEED_NONE)
    {
      if (mImitaterButton->IsMouseOver() != 0)
        return mApp->SetCursor(1);
    }
    else if (SeedNotAllowedToPick((SeedType)aSeedType) == 0)
    {
      return mApp->SetCursor(1);
    }
  }
  return mApp->SetCursor(0);
}

// ==========================================================================
// SeedChooserScreen::ShowToolTip(int)
// @0014D5D8  1864 bytes
// ==========================================================================
int SeedChooserScreen::ShowToolTip(int thePlayerIndex)
{
  if (thePlayerIndex > 1)
    return 0;

  // The tooltip only exists while the app is active.
  if (!mApp->mActive)
    return RemoveToolTip(thePlayerIndex);

  ToolTipWidget *aToolTip = (thePlayerIndex != 0) ? mToolTip2 : mToolTip1;
  int &aToolTipSeed = (thePlayerIndex != 0) ? mToolTipSeed2 : mToolTipSeed1;

  if (mApp->GetDialogCount() > 0 || mChooseState == CHOOSE_VIEW_LAWN)
    return RemoveToolTip(thePlayerIndex);
  if (mSeedsInFlight > 0)
    return 0;

  const int aCursorSeed = (thePlayerIndex != 0) ? mSeedIndex2 : mSeedIndex1;
  const int aCursorX = (thePlayerIndex != 0) ? mCursorPositionX2 : mCursorPositionX1;
  const int aCursorY = (thePlayerIndex != 0) ? mCursorPositionY2 : mCursorPositionY1;

  // Hovering the Imitater button describes the Imitater itself, not a packet.
  if (!mIsZombieChooser && aCursorSeed == SEED_IMITATER && mMouseVisible)
  {
    aToolTip->SetLabel(Plant::GetToolTip(SEED_IMITATER));
    aToolTip->SetTitle(Plant::GetNameString(SEED_IMITATER, SEED_NONE));
    aToolTip->SetWarningText("");
    aToolTip->mVisible = true;
    aToolTip->mX = mImitaterButton->mX + 63;
    aToolTip->mY = mImitaterButton->mY;
    aToolTipSeed = SEED_IMITATER;
    return aToolTip->mX;
  }

  const int aSeedType = SeedHitTest(aCursorX, aCursorY);
  if (aSeedType == SEED_NONE)
    return RemoveToolTip(thePlayerIndex);
  if (aSeedType == aToolTipSeed)
    return aSeedType;

  RemoveToolTip(thePlayerIndex);

  const int aSeedPacketIndex = GetSeedPacketIndex((SeedType)aSeedType);
  const unsigned int aRecFlags = SeedNotRecommendedToPick((SeedType)aSeedType);

  // The warning line explains why this packet cannot be used here. Bit 0 of the
  // recommendation flags is NOT_RECOMMENDED_NOCTURNAL.
  if (SeedNotAllowedToPick((SeedType)aSeedType) != 0)
    aToolTip->SetWarningText("[NOT_ALLOWED_ON_THIS_LEVEL]");
  else if (SeedNotAllowedDuringTrial((SeedType)aSeedType) != 0)
    aToolTip->SetWarningText("[FULL_VERSION_ONLY]");
  else if (mChosenSeeds[aSeedPacketIndex].mSeedState == SEED_IN_BANK
      && mChosenSeeds[aSeedPacketIndex].mCrazyDavePicked)
    aToolTip->SetWarningText("[CRAZY_DAVE_WANTS]");
  else if (aRecFlags == 0)
    aToolTip->SetWarningText("");
  else if ((aRecFlags & 1) != 0)
    aToolTip->SetWarningText("[NOCTURNAL_WARNING]");
  else
    aToolTip->SetWarningText("[NOT_RECOMMENDED_FOR_LEVEL]");

  if (aSeedType == SEED_IMITATER)
  {
    const SeedType aImitaterType = mChosenSeeds[aSeedPacketIndex].mImitaterType;
    aToolTip->SetTitle(Plant::GetNameString(SEED_IMITATER, aImitaterType));
    aToolTip->SetLabel(Plant::GetToolTip(aImitaterType));
  }
  else if (!mIsZombieChooser)
  {
    aToolTip->SetTitle(Plant::GetNameString((SeedType)aSeedType, SEED_NONE));
    aToolTip->SetLabel(Plant::GetToolTip((SeedType)aSeedType));
  }
  else if (aSeedType == SEED_ZOMBIE_GRAVESTONE)
  {
    Sexy::String aTitle;
    TodStringTranslate(&aTitle, "[ZOMBIE_GRAVESTONE]");
    aToolTip->SetTitle(aTitle);

    Sexy::String aLabel;
    TodStringTranslate(&aLabel, "[ZOMBIE_GRAVESTONE_DESCRIPTION]");
    aToolTip->SetLabel(aLabel);
  }
  else
  {
    const ZombieType aZombieType = Challenge::IZombieSeedTypeToZombieType((SeedType)aSeedType);
    if (aZombieType == ZOMBIE_INVALID)
      return 0;

    // GetZombieDefinition returns a ZombieDefinition*; the tree declares it as a
    // plain word, so the name field at +24 is read through the returned value.
    const char *aZombieName = *(const char **)GetZombieDefinition(aZombieType)->mZombieName;

    Sexy::String aFormat;
    StrFormat(&aFormat, "[%s]", aZombieName);

    Sexy::String aTitle;
    TodStringTranslate(&aTitle, aFormat.c_str());
    aToolTip->SetTitle(aTitle);

    StrFormat(&aFormat, "[%s_DESCRIPTION_HEADER]", aZombieName);

    Sexy::String aLabel;
    TodStringTranslate(&aLabel, aFormat.c_str());
    aToolTip->SetLabel(aLabel);
  }

  int aSeedX = 0;
  int aSeedY = 0;
  GetSeedPositionInChooser(aSeedPacketIndex, aSeedX, aSeedY);

  // Centre the tooltip over the packet, but keep it inside the chooser.
  int aToolTipX = mX + 14;
  const int aCenteredX = mX + aSeedX + (50 - aToolTip->mWidth) / 2;
  if (aCenteredX > mX + 14)
  {
    aToolTipX = mX + mWidth - aToolTip->mWidth - 14;
    if (aToolTipX >= aCenteredX)
      aToolTipX = aCenteredX;
  }

  int aToolTipY = aSeedY;
  if (aSeedPacketIndex > 39)
    aToolTipX = aSeedX + 53;
  else
    aToolTipY += 70;

  aToolTip->mX = aToolTipX;
  aToolTip->mY = aToolTipY;
  aToolTip->mVisible = true;
  aToolTip->mMaxBottom = (aToolTipY <= 529) ? 600 : 529;
  aToolTipSeed = aSeedType;
  return aToolTip->mMaxBottom;
}

// ==========================================================================
// SeedChooserScreen::FindSeedInBank(int,int)
// @0014DD58  92 bytes
// ==========================================================================
int SeedChooserScreen::FindSeedInBank(int theIndexInBank, int thePlayerIndex)
{
  // theIndexInBank is a slot in the bank, thePlayerIndex the player whose bank it is.
  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    const SeedType aSeedType = mIsZombieChooser ? (SeedType)GetZombieSeedType(i) : (SeedType)i;
    const ChosenSeedData &aChosenSeed = mChosenSeeds[i];
    if (HasPacket(aSeedType, mIsZombieChooser) != 0
        && aChosenSeed.mSeedState == SEED_IN_BANK
        && aChosenSeed.mSeedIndexInBank == theIndexInBank
        && aChosenSeed.mChosenPlayerIndex == thePlayerIndex)
      return aChosenSeed.mSeedType;
  }
  return SEED_NONE;
}

// ==========================================================================
// SeedChooserScreen::CloseSeedChooser()
// @0014DDB4  354 bytes
// ==========================================================================
int SeedChooserScreen::CloseSeedChooser()
{
  // Hand every chosen packet over to the seed bank, refresh timers included.
  for (int aBankIndex = 0; aBankIndex < mSeedBank1->mNumPackets; ++aBankIndex)
  {
    const int aSeedInBank = FindSeedInBank(aBankIndex, mIsZombieChooser);
    const ChosenSeedData &aChosenSeed = mChosenSeeds[GetSeedPacketIndex((SeedType)aSeedInBank)];
    SeedPacket &aPacket = mSeedBank1->mSeedPackets[aBankIndex];
    aPacket.SetPacketType(aChosenSeed.mSeedType, aChosenSeed.mImitaterType);
    if (aChosenSeed.mRefreshing)
    {
      aPacket.mRefreshCounter = aChosenSeed.mRefreshCounter;
      aPacket.mRefreshTime = Plant::GetRefreshTime(aPacket.mPacketType, aPacket.mImitaterType);
      aPacket.mRefreshing = true;
      aPacket.mActive = false;
    }

    if (mApp->IsCoopMode())
    {
      const int aSeedInBank2 = FindSeedInBank(aBankIndex, 1);
      const ChosenSeedData &aChosenSeed2 = mChosenSeeds[GetSeedPacketIndex((SeedType)aSeedInBank2)];
      SeedPacket &aPacket2 = mSeedBank2->mSeedPackets[aBankIndex];
      aPacket2.SetPacketType(aChosenSeed2.mSeedType, aChosenSeed2.mImitaterType);
      if (aChosenSeed2.mRefreshing)
      {
        aPacket2.mRefreshCounter = aChosenSeed2.mRefreshCounter;
        aPacket2.mRefreshTime = Plant::GetRefreshTime(aPacket2.mPacketType, aPacket2.mImitaterType);
        aPacket2.mRefreshing = true;
        aPacket2.mActive = false;
      }
    }
  }

  if (mApp->mGameMode != GAMEMODE_MP_VS)
  {
    mBoard->mCutScene->EndSeedChooser();
    return 0;
  }

  // VS mode hands control back to the setup menu instead of starting the level.
  int aResult;
  if (mIsZombieChooser)
  {
    aResult = mApp->mVSSetupMenu->EndZombieChooser();
    if (mApp->mSeedChooserScreen != nullptr)
      return aResult;
  }
  else
  {
    aResult = mApp->mVSSetupMenu->EndSeedChooser();
    if (mApp->mSeedChooserScreen != nullptr)
      return aResult;
  }

  if (mApp->mZombieChooserScreen == nullptr)
    mApp->mVSSetupMenu->CloseVSSetup(false);
  return aResult;
}

// ==========================================================================
// SeedChooserScreen::OnStartButton()
// @0014DF18  1056 bytes
// ==========================================================================
int SeedChooserScreen::OnStartButton()
{
  // Survival levels fix the seed list up front: the level is only ready once
  // the bank holds exactly the configured number of packets.
  const int aNumConfiguredSeeds = (int)mApp->mLevel.mSeedConfig.size();
  if (aNumConfiguredSeeds != 0)
  {
    const int aSeedBankLimit = mApp->mLevel.mSeedBankLimit;
    if (aSeedBankLimit <= 0)
    {
      if (mBoard->GetNumSeedsInBank(false) == aNumConfiguredSeeds)
        return CloseSeedChooser();
    }
    else if (aSeedBankLimit == aNumConfiguredSeeds)
    {
      return CloseSeedChooser();
    }
  }

  if (mApp->mGameMode == GAMEMODE_CHALLENGE_SEEING_STARS
      && PickedPlantType(SEED_STARFRUIT) == 0
      && mApp->mLevel.isSeedForbidden(SEED_STARFRUIT) == 0)
  {
    if (!DisplayRepickWarningDialog("[SEED_CHOOSER_SEEING_STARS_WARNING]"))
      return 0;
  }

  // Nothing else to check unless this is level 1-5 without a Puff-shroom.
  if (!mApp->IsFirstTimeAdventureMode()
      || mBoard->mLevel != 11
      || PickedPlantType(SEED_PUFFSHROOM) != 0
      || mApp->mLevel.isSeedForbidden(SEED_PUFFSHROOM) != 0
      || DisplayRepickWarningDialog("[SEED_CHOOSER_PUFFSHROOM_WARNING]"))
  {
    if (PickedPlantType(SEED_SUNFLOWER) != 0
        || mApp->mLevel.isSeedForbidden(SEED_SUNFLOWER) != 0
        || PickedPlantType(SEED_TWINSUNFLOWER) != 0
        || mApp->mLevel.isSeedForbidden(SEED_TWINSUNFLOWER) != 0
        || PickedPlantType(SEED_SUNSHROOM) != 0
        || mApp->mLevel.isSeedForbidden(SEED_SUNSHROOM) != 0
        || mBoard->mCutScene->IsSurvivalRepick()
        || mApp->mGameMode == GAMEMODE_CHALLENGE_LAST_STAND)
    {
      // A pool level with no way to plant on water gets a warning.
      if (mBoard->StageHasPool()
          && PickedPlantType(SEED_LILYPAD) == 0
          && mApp->mLevel.isSeedForbidden(SEED_LILYPAD) == 0
          && PickedPlantType(SEED_SEASHROOM) == 0
          && mApp->mLevel.isSeedForbidden(SEED_SEASHROOM) == 0
          && PickedPlantType(SEED_TANGLEKELP) == 0
          && mApp->mLevel.isSeedForbidden(SEED_TANGLEKELP) == 0
          && !mBoard->mCutScene->IsSurvivalRepick())
      {
        if (mApp->IsFirstTimeAdventureMode() && mBoard->mLevel == 21)
        {
          if (!DisplayRepickWarningDialog("[SEED_CHOOSER_LILY_WARNING]"))
            return 0;
        }
        else if (!DisplayRepickWarningDialog("[SEED_CHOOSER_POOL_WARNING]"))
        {
          return 0;
        }
      }
    }
    else if (mApp->IsFirstTimeAdventureMode() && mBoard->mLevel == 11)
    {
      if (!DisplayRepickWarningDialog("[SEED_CHOOSER_NIGHT_SUN_WARNING]"))
        return 0;
    }
    else if (!DisplayRepickWarningDialog("[SEED_CHOOSER_SUN_WARNING]"))
    {
      return 0;
    }

    // Roof levels want a Flower Pot.
    if (!mBoard->StageHasRoof()
        || PickedPlantType(SEED_FLOWERPOT) != 0
        || mApp->mLevel.isSeedForbidden(SEED_FLOWERPOT) != 0
        || mApp->HasSeedType(SEED_FLOWERPOT, false) == 0
        || DisplayRepickWarningDialog("[SEED_CHOOSER_ROOF_WARNING]"))
    {
      if (mApp->mGameMode == GAMEMODE_CHALLENGE_ART_CHALLENGE_WALLNUT
          && PickedPlantType(SEED_WALLNUT) == 0)
      {
        if (!DisplayRepickWarningDialog("[SEED_CHOOSER_ART_WALLNUT_WARNING]"))
          return 0;
      }

      // Art Challenge: Sunflower wants Starfruit, Umbrella Leaf and Wall-nut.
      const bool aArtChallengeOk = mApp->mGameMode != GAMEMODE_CHALLENGE_ART_CHALLENGE_SUNFLOWER
          || (PickedPlantType(SEED_STARFRUIT) != 0
              && PickedPlantType(SEED_UMBRELLA) != 0
              && PickedPlantType(SEED_WALLNUT) != 0)
          || DisplayRepickWarningDialog("[SEED_CHOOSER_ART_2_WARNING]");

      const bool aFlyerProtectionOk = FlyersAreComing() == 0
          || FlyProtectionCurrentlyPlanted() != 0
          || PickedPlantType(SEED_CATTAIL) != 0
          || mApp->mLevel.isSeedForbidden(SEED_CATTAIL) != 0
          || PickedPlantType(SEED_CACTUS) != 0
          || mApp->mLevel.isSeedForbidden(SEED_CACTUS) != 0
          || PickedPlantType(SEED_BLOVER) != 0
          || mApp->mLevel.isSeedForbidden(SEED_BLOVER) != 0
          || DisplayRepickWarningDialog("[SEED_CHOOSER_FLYER_WARNING]");

      if (aArtChallengeOk && aFlyerProtectionOk)
      {
        // Every upgraded plant asks before it replaces the base one.
        static const int aUpgrades[][2] = {
          { SEED_GATLINGPEA, SEED_REPEATER },
          { SEED_WINTERMELON, SEED_MELONPULT },
          { SEED_TWINSUNFLOWER, SEED_SUNFLOWER },
          { SEED_SPIKEROCK, SEED_SPIKEWEED },
          { SEED_COBCANNON, SEED_KERNELPULT },
          { SEED_GOLD_MAGNET, SEED_MAGNETSHROOM },
          { SEED_GLOOMSHROOM, SEED_FUMESHROOM },
          { SEED_CATTAIL, SEED_LILYPAD },
        };
        for (int i = 0; i < (int)(sizeof(aUpgrades) / sizeof(aUpgrades[0])); ++i)
        {
          if (CheckSeedUpgrade(aUpgrades[i][0], aUpgrades[i][1]) == 0)
            return 0;
        }
        return CloseSeedChooser();
      }
    }
  }
  return 0;
}

// ==========================================================================
// SeedChooserScreen::ClickedSeedInBank(ChosenSeed &,int)
// @0014E360  404 bytes
// ==========================================================================
int SeedChooserScreen::ClickedSeedInBank(ChosenSeedData & theChosenSeed, int theGamepadIndex)
{
  // The seed bank belongs to the player whose gamepad clicked it.
  const int aPlayerIndex = mBoard->mGamepadControls[theGamepadIndex]->mPlayerIndex;
  if (mApp->IsCoopMode() && aPlayerIndex != theChosenSeed.mChosenPlayerIndex)
    return 0;

  int aNumPackets = mSeedBank1->mNumPackets;
  if (mApp->IsCoopMode())
    aNumPackets = 4;

  // Everything after the clicked packet slides one slot down the bank.
  for (int aBankIndex = theChosenSeed.mSeedIndexInBank + 1; aBankIndex < aNumPackets; ++aBankIndex)
  {
    const int aOtherPlayerIndex =
        (!mApp->IsCoopMode() && mApp->mGameMode != GAMEMODE_MP_VS) ? 0 : aPlayerIndex;
    const int aSeedInBank = FindSeedInBank(aBankIndex, aOtherPlayerIndex);
    if (aSeedInBank == SEED_NONE)
      continue;

    ChosenSeedData &aOther = mChosenSeeds[aSeedInBank];
    aOther.mStartX = aOther.mX;
    aOther.mStartY = aOther.mY;
    aOther.mTimeStartMotion = mSeedChooserAge;
    aOther.mTimeEndMotion = mSeedChooserAge + 15;
    GetSeedPositionInBank(aBankIndex - 1, aOther.mEndX, aOther.mEndY, aOther.mChosenPlayerIndex);
    aOther.mSeedState = SEED_FLYING_TO_BANK;
    aOther.mSeedIndexInBank = aBankIndex - 1;
    ++mSeedsInFlight;
  }

  // The clicked packet flies back out to the chooser.
  theChosenSeed.mTimeStartMotion = mSeedChooserAge;
  theChosenSeed.mTimeEndMotion = mSeedChooserAge + 25;
  theChosenSeed.mStartX = theChosenSeed.mX;
  theChosenSeed.mStartY = theChosenSeed.mY;
  GetSeedPositionInChooser(GetSeedPacketIndex(theChosenSeed.mSeedType), theChosenSeed.mEndX, theChosenSeed.mEndY);
  theChosenSeed.mSeedState = SEED_FLYING_TO_CHOOSER;
  theChosenSeed.mSeedIndexInBank = 0;
  ++mSeedsInFlight;
  --mSeedsInBank;

  if (aPlayerIndex == 1 && mApp->IsCoopMode())
    --mSeedsIn2PBank;
  else
    --mSeedsIn1PBank;

  RemoveToolTip(aPlayerIndex);
  EnableStartButton(false);
  mApp->PlaySample(SOUND_TAP, true);
  return 0;
}

// ==========================================================================
// SeedChooserScreen::UpdateImitaterButton()
// @0014E4FC  80 bytes
// ==========================================================================
void SeedChooserScreen::UpdateImitaterButton()
{
  if (mImitaterButton == nullptr)
    return;

  // The Imitater is only offered in the plant chooser, to a profile that has
  // unlocked it, and never in VS mode.
  if (mIsZombieChooser || HasPacket(SEED_IMITATER, mIsZombieChooser) == 0
      || mApp->mGameMode == GAMEMODE_MP_VS)
  {
    mImitaterButton->mBtnNoDraw = true;
    mImitaterButton->mDisabled = true;
    return;
  }

  mImitaterButton->mBtnNoDraw = false;
  mImitaterButton->SetDisabled(mChosenSeeds[SEED_IMITATER].mSeedState != SEED_PACKET_HIDDEN);
}

// ==========================================================================
// SeedChooserScreen::LandFlyingSeed(ChosenSeed &)
// @0014E54C  98 bytes
// ==========================================================================
void SeedChooserScreen::LandFlyingSeed(ChosenSeedData & theChosenSeed)
{
  if (theChosenSeed.mSeedState == SEED_FLYING_TO_BANK)
  {
    theChosenSeed.mX = theChosenSeed.mEndX;
    theChosenSeed.mY = theChosenSeed.mEndY;
    theChosenSeed.mTimeStartMotion = 0;
    theChosenSeed.mTimeEndMotion = 0;
    theChosenSeed.mSeedState = SEED_IN_BANK;
    --mSeedsInFlight;
  }
  else if (theChosenSeed.mSeedState == SEED_FLYING_TO_CHOOSER)
  {
    theChosenSeed.mX = theChosenSeed.mEndX;
    theChosenSeed.mY = theChosenSeed.mEndY;
    theChosenSeed.mTimeStartMotion = 0;
    theChosenSeed.mTimeEndMotion = 0;
    theChosenSeed.mSeedState = SEED_IN_CHOOSER;
    --mSeedsInFlight;

    // A landed Imitater hides itself and waits for a plant to copy.
    if (theChosenSeed.mSeedType == SEED_IMITATER)
    {
      theChosenSeed.mSeedState = SEED_PACKET_HIDDEN;
      theChosenSeed.mImitaterType = SEED_NONE;
      UpdateImitaterButton();
    }
  }
}

// ==========================================================================
// SeedChooserScreen::UpdateAfterPurchase()
// @0014E5B0  194 bytes
// ==========================================================================
void SeedChooserScreen::UpdateAfterPurchase()
{
  // Re-seat every packet that has a home: banked ones onto their bank slot,
  // chooser ones onto their grid slot.
  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    ChosenSeedData &aChosenSeed = mChosenSeeds[i];
    if (aChosenSeed.mSeedState == SEED_IN_BANK)
      GetSeedPositionInBank(aChosenSeed.mSeedIndexInBank, aChosenSeed.mX, aChosenSeed.mY, aChosenSeed.mChosenPlayerIndex);
    else if (aChosenSeed.mSeedState == SEED_IN_CHOOSER)
      GetSeedPositionInChooser(i, aChosenSeed.mX, aChosenSeed.mY);
    else
      continue;

    aChosenSeed.mStartX = aChosenSeed.mX;
    aChosenSeed.mStartY = aChosenSeed.mY;
    aChosenSeed.mEndX = aChosenSeed.mX;
    aChosenSeed.mEndY = aChosenSeed.mY;
  }

  const int aNumPackets = mApp->IsCoopMode()
      ? (mSeedBank1->mNumPackets + mSeedBank2->mNumPackets)
      : mSeedBank1->mNumPackets;
  EnableStartButton(mSeedsInBank == aNumPackets);
  UpdateImitaterButton();
}

// ==========================================================================
// SeedChooserScreen::PickRandomSeeds()
// @0014E674  194 bytes
// ==========================================================================
int SeedChooserScreen::PickRandomSeeds()
{
  // Fill the bank with random unlocked packets until it is full. The draw is
  // unbounded on purpose: it keeps rolling until it lands on a usable packet.
  int aBankIndex = mSeedsInBank;
  while (aBankIndex < mSeedBank1->mNumPackets)
  {
    int aSeedType;
    do
    {
      aSeedType = Rand(mApp->GetSeedsAvailable(mIsZombieChooser));
    }
    while (HasPacket(aSeedType, mIsZombieChooser) == 0);

    if (aSeedType == SEED_IMITATER || mChosenSeeds[aSeedType].mSeedState != SEED_IN_CHOOSER)
      continue;

    ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedType];
    aChosenSeed.mTimeStartMotion = 0;
    aChosenSeed.mTimeEndMotion = 0;
    aChosenSeed.mStartX = aChosenSeed.mX;
    aChosenSeed.mStartY = aChosenSeed.mY;
    GetSeedPositionInBank(aBankIndex, aChosenSeed.mEndX, aChosenSeed.mEndY, 0);
    aChosenSeed.mSeedIndexInBank = aBankIndex++;
    aChosenSeed.mSeedState = SEED_IN_BANK;
    ++mSeedsInBank;
  }

  // Anything already in flight still has to land before the screen closes.
  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
    LandFlyingSeed(mChosenSeeds[i]);
  return CloseSeedChooser();
}

// ==========================================================================
// SeedChooserScreen::KeyChar(char)
// @0014E738  70 bytes
// ==========================================================================
int SeedChooserScreen::KeyChar(char theChar)
{
  if (mChooseState == CHOOSE_VIEW_LAWN)
  {
    // Enter, space or escape bring the chooser back from the lawn view.
    if (theChar == 13 || theChar == 32 || theChar == 27)
    {
      CancelLawnView();
      return 1;
    }
  }
  else if (mApp->mTodCheatKeys && theChar == 27)
  {
    // The debug "random seeds" hotkey.
    PickRandomSeeds();
    return 1;
  }

  mBoard->KeyChar(theChar);
  return 1;
}

// ==========================================================================
// SeedChooserScreen::ButtonDepress(int)
// @0014E780  236 bytes
// ==========================================================================
void SeedChooserScreen::ButtonDepress(int theId)
{
  if (mSeedsInFlight > 0 || mChooseState == CHOOSE_VIEW_LAWN || !mMouseVisible)
    return;

  if (theId == SeedChooserScreen_ViewLawn)
  {
    mChooseState = CHOOSE_VIEW_LAWN;
    mViewLawnTime = 0;
    ((LawnApp *)gLawnApp)->HideHelpBarWidget();
  }
  else if (theId == SeedChooserScreen_Almanac)
  {
    AlmanacDialog *aDialog = mApp->DoAlmanacDialog(SEED_NONE, ZOMBIE_INVALID);
    aDialog->WaitForResult(true);
    // 6 == MUSIC_TUNE_CHOOSE_YOUR_SEEDS; MusicTune is a one-int surrogate in
    // Sexy\ReconTypes.h with no enumerators.
    mApp->mMusic->MakeSureMusicIsPlaying(MusicTune(6));
  }
  else if (theId == SeedChooserScreen_Store)
  {
    StoreScreen *aStore = mApp->ShowStoreScreen();
    aStore->WaitForResult(false);
    bool aGoToTreeNow = aStore->mGoToTreeNow;
    mApp->KillStoreScreen();
    if (aGoToTreeNow)
    {
      // Buying the Tree of Wisdom jumps straight out of the level.
      mApp->KillBoard();
      mApp->PreNewGame(GAMEMODE_TREE_OF_WISDOM, false);
      return;
    }
    mWidgetManager->SetFocus(this);
    mApp->mMusic->MakeSureMusicIsPlaying(MusicTune(6));
  }
  else
  {
    if (mApp->GetSeedsAvailable(mIsZombieChooser) < mSeedBank1->mNumPackets)
      return;
    if (theId == SeedChooserScreen_Start)
      OnStartButton();
    else if (theId == SeedChooserScreen_Random)
      PickRandomSeeds();
    return;
  }

  mApp->GetSeedsAvailable(mIsZombieChooser);
}

// ==========================================================================
// SeedChooserScreen::ShouldDisplayCursor(int)
// @0014E87C  62 bytes
// ==========================================================================
int SeedChooserScreen::ShouldDisplayCursor(int thePlayerIndex)
{
  GamepadControls *aControls = mBoard->mGamepadControls[thePlayerIndex];
  // -1 means the pad is unassigned; in VS mode only the player whose turn it is
  // gets a cursor.
  if (aControls->mGamepadIndex == -1
      || (mApp->mGameMode == GAMEMODE_MP_VS && aControls->mGamepadIndex != mPlayerIndex))
    return 0;

  // Once a button holds the gamepad cursor, only player 1 keeps a free cursor.
  if (mSelectedButton == nullptr)
    return 1;
  return (thePlayerIndex != 0) ? 1 : 0;
}

// ==========================================================================
// SeedChooserScreen::CanPickNow()
// @0014E8BC  52 bytes
// ==========================================================================
bool SeedChooserScreen::CanPickNow()
{
  if (mApp->mGameMode != GAMEMODE_MP_VS)
    return true;

  // VS mode alternates: only the side whose pick turn it is may choose.
  VSSetupMenu *aSetup = mApp->mVSSetupMenu;
  const VSSetupMenu::VSSide aTurn = aSetup->mSides[aSetup->mSeedPickTurn];
  return mApp->GamepadToPlayerIndex(mPlayerIndex) == aTurn;
}

// ==========================================================================
// SeedChooserScreen::ClickedSeedInChooser(ChosenSeed &,int)
// @0014E8F0  452 bytes
// ==========================================================================
int SeedChooserScreen::ClickedSeedInChooser(ChosenSeedData & theChosenSeed, int thePlayerIndex)
{
  const int aGamepadIndex = mApp->PlayerToGamepadIndex(thePlayerIndex);

  if (mApp->IsCoopMode())
  {
    if (mSeedsInBank > 8)
      return 0;
  }
  else
  {
    if (mSeedsInBank == mSeedBank1->mNumPackets)
      return 0;
    if (mApp->mGameMode == GAMEMODE_MP_VS && !CanPickNow())
    {
      mApp->PlaySample(SOUND_BUZZER, true);
      return 0;
    }
  }

  // Co-op players only get four of the eight shared slots each.
  if (!mApp->IsCoopMode() || (thePlayerIndex == 1 ? mSeedsIn2PBank : mSeedsIn1PBank) <= 3)
  {
    const int aBankSlot = (mApp->IsCoopMode() && thePlayerIndex == 1) ? mSeedsIn2PBank : mSeedsIn1PBank;

    theChosenSeed.mTimeStartMotion = mSeedChooserAge;
    theChosenSeed.mTimeEndMotion = mSeedChooserAge + 25;
    theChosenSeed.mStartX = theChosenSeed.mX;
    theChosenSeed.mStartY = theChosenSeed.mY;

    // Which bank the packet is credited to: adventure is always player 1, VS
    // follows the setup menu's side for this gamepad, everything else is the
    // clicking player.
    int aChosenPlayerIndex;
    if (mApp->IsAdventureMode())
      aChosenPlayerIndex = 0;
    else if (mApp->mGameMode == GAMEMODE_MP_VS)
      aChosenPlayerIndex = mApp->mVSSetupMenu->mSides[thePlayerIndex];
    else
      aChosenPlayerIndex = thePlayerIndex;
    theChosenSeed.mChosenPlayerIndex = aChosenPlayerIndex;

    GetSeedPositionInBank(aBankSlot, theChosenSeed.mEndX, theChosenSeed.mEndY, aChosenPlayerIndex);
    theChosenSeed.mSeedIndexInBank = aBankSlot;
    theChosenSeed.mSeedState = SEED_FLYING_TO_BANK;
    ++mSeedsInFlight;
    ++mSeedsInBank;
    if (mApp->IsCoopMode() && thePlayerIndex == 1)
      ++mSeedsIn2PBank;
    else
      ++mSeedsIn1PBank;

    RemoveToolTip(thePlayerIndex);
    mApp->PlaySample(SOUND_TAP, true);

    if (mSeedsInBank == mSeedBank1->mNumPackets && !mApp->IsCoopMode())
      EnableStartButton(true);
    if (mApp->IsCoopMode() && mSeedsInBank == mSeedBank1->mNumPackets + mSeedBank2->mNumPackets)
      EnableStartButton(true);

    if (mApp->mGameMode == GAMEMODE_MP_VS && mApp->mVSSetupMenu != nullptr)
      return mApp->mVSSetupMenu->OnPlayerPickedSeed(aGamepadIndex);
  }
  return 0;
}

// ==========================================================================
// SeedChooserScreen::OnKeyDown(Sexy::KeyCode,unsigned int)
// @0014EE3C  1982 bytes
// ==========================================================================
int SeedChooserScreen::OnKeyDown(Sexy::KeyCode theKey, unsigned int theFlags)
{
  // Key codes 304/305 are the modifier keys; they never drive the chooser.
  if ((unsigned int)(theKey - 304) <= 1)
    return 0;

  // Any packet still in flight has to land before navigation continues.
  if (mSeedsInFlight > 0)
  {
    for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
      LandFlyingSeed(mChosenSeeds[i]);
  }

  if (mBoard->mGamepadControls[0]->mGamepadIndex == -1)
    return 0;

  // While the lawn is in view, Enter brings the chooser back.
  if (mChooseState == CHOOSE_VIEW_LAWN && theKey == KEYCODE_RETURN)
  {
    if (CancelLawnView() != 0)
    {
      RebuildHelpbar();
      return 1;
    }
    GetNextSeedInDir(mSeedIndex1, SEED_DIR_DOWN);
  }
  else
  {
    const int aNextSeed = GetNextSeedInDir(mSeedIndex1, SEED_DIR_DOWN);
    if (aNextSeed == mSeedIndex1 && theKey == KEYCODE_DOWN && mSelectedButton == nullptr)
    {
      // Down at the bottom of the grid moves the gamepad cursor onto the
      // nearest visible, enabled button instead.
      const int aNumButtons = (int)mButtons.size();
      if (aNumButtons != 0)
      {
        int aBestDistance = -1;
        for (int i = 0; i < aNumButtons; ++i)
        {
          Widget *aButton = mButtons[i];
          if (!aButton->mVisible || aButton->mDisabled)
            continue;

          const Point aCenter = aButton->GetAbsCenter();
          const int aDx = aCenter.mX - mCursorPositionX1;
          const int aDy = aCenter.mY - mCursorPositionY1;
          const int aDistance = aDx * aDx + aDy * aDy;
          if (aBestDistance < 0 || aDistance < aBestDistance)
          {
            aBestDistance = aDistance;
            mSelectedButton = mButtons[i];
          }
        }

        if (mSelectedButton != nullptr)
        {
          mSelectedButton->mIsOver = true;
          return 1;
        }
      }

      mSeedIndex1 = GetNextSeedInDir(mSeedIndex1, SEED_DIR_DOWN);
      GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
      return 1;
    }
  }

  if (mSelectedButton == nullptr)
  {
    // No button holds the cursor: the keys act on the seed grid.
    switch (theKey)
    {
      case KEYCODE_RETURN:
      {
        // Enter on the Imitater packet opens the copy dialog, or banks it if it
        // is already chosen.
        if (mSeedIndex1 == SEED_IMITATER && mSeedsInBank < mSeedBank1->mNumPackets)
        {
          if (mChosenSeeds[SEED_IMITATER].mSeedState == SEED_IN_BANK)
          {
            ClickedSeedInBank(mApp->mSeedChooserScreen->mChosenSeeds[SEED_IMITATER], 0);
          }
          else
          {
            ImitaterDialog *aDialog = new ImitaterDialog(0);
            AddWidget(aDialog);
            aDialog->Resize((800 - aDialog->mWidth) / 2, (600 - aDialog->mHeight) / 2,
                            aDialog->mWidth, aDialog->mHeight);
            mApp->mWidgetManager->SetFocus(aDialog);
            mImitaterDialog = aDialog;
          }
          return 1;
        }

        const int aSeedType = SeedHitTest(mCursorPositionX1, mCursorPositionY1);
        if (aSeedType == SEED_NONE)
          return 0;

        if (SeedNotAllowedToPick((SeedType)aSeedType) != 0)
        {
          mApp->PlaySample(SOUND_BUZZER, true);
          return 1;
        }

        if (SeedNotAllowedDuringTrial((SeedType)aSeedType) != 0)
        {
          mApp->PlaySample(SOUND_TAP, true);
          if (mApp->LawnMessageBox(51, "[GET_FULL_VERSION_TITLE]", "[GET_FULL_VERSION_BODY]",
                                   "[GET_FULL_VERSION_YES_BUTTON]", "[GET_FULL_VERSION_NO_BUTTON]", 1) != 1000)
            return 1;
          mApp->BuyFullVersion();
          mApp->DoBackToMain();
          return 1;
        }

        ChosenSeedData &aChosenSeed = mChosenSeeds[GetSeedPacketIndex((SeedType)aSeedType)];
        if (aChosenSeed.mSeedState == SEED_IN_BANK)
        {
          if (aChosenSeed.mCrazyDavePicked)
          {
            mApp->PlaySample(SOUND_BUZZER, true);
            mToolTip1->FlashWarning();
          }
          else
          {
            if (mApp->mGameMode == GAMEMODE_MP_VS)
              return 0;
            ClickedSeedInBank(aChosenSeed, 0);
          }
          return 1;
        }

        if (aChosenSeed.mSeedState != SEED_IN_CHOOSER)
          return 0;

        ClickedSeedInChooser(aChosenSeed, 0);

        // Then walk the grid for the next packet that is actually usable.
        int aNumRows;
        if (mApp->mGameMode == GAMEMODE_MP_VS)
          aNumRows = 5;
        else if (Has7Rows() != 0)
          aNumRows = 6;
        else
          aNumRows = 5;

        bool aStop = false;
        while (!aStop)
        {
          const int aHit = SeedHitTest(mCursorPositionX1, mCursorPositionY1);
          if (aHit == -1)
            aStop = true;
          if (aStop)
            break;

          if (mChosenSeeds[GetSeedPacketIndex((SeedType)aHit)].mSeedState > SEED_IN_BANK
              && SeedNotRecommendedToPick((SeedType)aHit) == 0)
            return 1;

          const int aNext = mSeedIndex1 + 1;
          mSeedIndex1 = aNext;
          if (aNext >= NumColumns() * aNumRows)
            mSeedIndex1 = NumColumns() * aNumRows - 1;
          GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
        }

        while (mSeedIndex1 < NumColumns() * aNumRows - 1)
        {
          mSeedIndex1 = mSeedIndex1 + 1;
          GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);

          const int aHit = SeedHitTest(mCursorPositionX1, mCursorPositionY1);
          if (aHit != -1
              && SeedNotRecommendedToPick((SeedType)aHit) == 0
              && (unsigned int)(mChosenSeeds[GetSeedPacketIndex((SeedType)aHit)].mSeedState - SEED_FLYING_TO_CHOOSER) <= 1)
            return 1;
        }

        int aHit;
        do
        {
          if (mSeedIndex1 <= 0)
            break;
          mSeedIndex1 = mSeedIndex1 - 1;
          GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
          aHit = SeedHitTest(mCursorPositionX1, mCursorPositionY1);
        }
        while (aHit == -1
            || SeedNotRecommendedToPick((SeedType)aHit) != 0
            || (unsigned int)(mChosenSeeds[GetSeedPacketIndex((SeedType)aHit)].mSeedState - SEED_FLYING_TO_CHOOSER) > 1);
        return 1;
      }

      case KEYCODE_ESCAPE:
      {
        if (mChooseState == CHOOSE_VIEW_LAWN)
          return 1;

        if (mApp->mGameMode != GAMEMODE_MP_VS)
        {
          // Crazy Dave's free packets can be handed back one at a time.
          int aFreeIndex = 0;
          while (aFreeIndex < NUM_SEEDS_IN_CHOOSER)
          {
            if (!mChosenSeeds[aFreeIndex].mCrazyDavePicked
                && mChosenSeeds[aFreeIndex].mSeedState == SEED_IN_BANK)
              break;
            ++aFreeIndex;
          }

          if (aFreeIndex != NUM_SEEDS_IN_CHOOSER && mSeedsInBank != 0)
          {
            int aTargetIndex;
            if (mApp->IsCoopMode())
            {
              aTargetIndex = 0;
              for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
              {
                if (mChosenSeeds[i].mChosenPlayerIndex == 0 && mChosenSeeds[i].mSeedState == SEED_IN_BANK)
                  ++aTargetIndex;
              }
            }
            else
            {
              aTargetIndex = mSeedsInBank;
            }
            --aTargetIndex;

            for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
            {
              ChosenSeedData &aChosenSeed = mChosenSeeds[i];
              if (aChosenSeed.mSeedState == SEED_IN_BANK
                  && aChosenSeed.mSeedIndexInBank == aTargetIndex
                  && !aChosenSeed.mCrazyDavePicked
                  && aChosenSeed.mChosenPlayerIndex == 0)
              {
                ClickedSeedInBank(aChosenSeed, 0);
                return 1;
              }
            }
            return 0;
          }
        }

        // Otherwise Escape offers to quit the level.
        Sexy::Dialog *aDialog = mApp->ConfirmQuit();
        mOpeningDialog = true;
        const int aResult = aDialog->WaitForResult(true);
        mOpeningDialog = false;
        if (aResult != 1000)
          return 1;
        mApp->PostLeaveLevel();
        mApp->SetBoardResult(BOARDRESULT_QUIT);
        mApp->DoBackToMain();
        return 1;
      }

      case KEYCODE_LEFT:
        mSeedIndex1 = GetNextSeedInDir(mSeedIndex1, SEED_DIR_LEFT);
        GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
        return 1;

      case KEYCODE_UP:
        mSeedIndex1 = GetNextSeedInDir(mSeedIndex1, SEED_DIR_UP);
        GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
        return 1;

      case KEYCODE_RIGHT:
        // The right-hand end of a row steps onto the Imitater button when the
        // profile owns one.
        if (mSeedIndex1 % 8 == 7 && HasPacket(SEED_IMITATER, false) != 0
            && mApp->mGameMode != GAMEMODE_MP_VS)
        {
          mSeedIndex1 = SEED_IMITATER;
          GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
          return 1;
        }
        mSeedIndex1 = GetNextSeedInDir(mSeedIndex1, SEED_DIR_RIGHT);
        GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
        return 1;

      case KEYCODE_DOWN:
        mSeedIndex1 = GetNextSeedInDir(mSeedIndex1, SEED_DIR_DOWN);
        GetSeedPositionInChooser(mSeedIndex1, mCursorPositionX1, mCursorPositionY1);
        return 1;

      default:
        return 0;
    }
  }

  // A button holds the cursor: move between buttons, or press the held one.
  GameButton *aSlotButton = mSelectedButton;
  const int aNumButtons = (int)mButtons.size();

  int aButtonIndex = aNumButtons;
  for (int i = 0; i < aNumButtons; ++i)
  {
    if (mButtons[i] == aSlotButton)
    {
      aButtonIndex = i;
      break;
    }
  }

  GameButton *aNewButton = nullptr;
  switch (theKey)
  {
    case KEYCODE_LEFT:
    {
      // Wrap backwards to the previous usable button.
      unsigned int aIndex = (unsigned int)(aButtonIndex + aNumButtons - 1);
      if (aIndex <= (unsigned int)aButtonIndex)
        return 1;
      while (true)
      {
        aNewButton = mButtons[aIndex % (unsigned int)aNumButtons];
        if (!aNewButton->mDisabled && aNewButton->mVisible)
          break;
        if (--aIndex <= (unsigned int)aButtonIndex)
          return 1;
      }
      if (aSlotButton == aNewButton)
        return 1;
      break;
    }
    case KEYCODE_RIGHT:
    {
      // Wrap forwards.
      unsigned int aIndex = (unsigned int)(aButtonIndex + 1);
      const unsigned int aLast = (unsigned int)(aButtonIndex + aNumButtons);
      if (aLast <= aIndex)
        return 1;
      while (true)
      {
        aNewButton = mButtons[aIndex % (unsigned int)aNumButtons];
        if (!aNewButton->mDisabled && aNewButton->mVisible)
          break;
        if (aLast <= ++aIndex)
          return 1;
      }
      if (aSlotButton == aNewButton)
        return 1;
      break;
    }
    case KEYCODE_UP:
      // Up drops the button cursor and hands the keys back to the grid.
      aSlotButton->mIsOver = false;
      mSelectedButton = nullptr;
      return 1;
    case KEYCODE_RETURN:
      aSlotButton->mIsDown = true;
      return 1;
    default:
      return 0;
  }

  aSlotButton->mIsOver = false;
  aSlotButton->mIsDown = false;
  aNewButton->mIsOver = true;
  mSelectedButton = aNewButton;
  return aNewButton->mVisible;
}

// ==========================================================================
// SeedChooserScreen::GameButtonDown(Sexy::GamepadButton,int,unsigned int)
// @0014F618  1304 bytes
// ==========================================================================
int SeedChooserScreen::GameButtonDown(Sexy::GamepadButton theGamepadIndex, int theButton, unsigned int theFlags)
{
  // Claim the pad for player 2 when only one gamepad is attached, so a second
  // pad plugged in mid-level can still join.
  unsigned int aPad = theFlags;
  int aSecondPad = mPlayerIndex;
  if (aSecondPad == 0 && aPad != 0 && mApp->mGamepads[0]->mStatus <= Sexy::Gamepad::STATUS_CONNECTED)
  {
    aPad = 0;
    mApp->SwapGamepadId(0, theFlags);
    aSecondPad = mPlayerIndex;
  }

  if (aPad != (unsigned int)aSecondPad)
  {
    const int aSecondPlayerPad = mApp->mSecondPlayerGamepadIndex;
    if (aSecondPlayerPad == -1 && theButton == GAMEPAD_BUTTON_START)
    {
      if (!mApp->IsAdventureMode())
        return 0;
      mApp->SetSecondPlayer(aPad);
    }
    else if (aSecondPlayerPad != (int)aPad)
    {
      return 0;
    }
  }

  const int aPlayerIndex = mApp->GamepadToPlayerIndex(aPad);

  if (mSeedsInFlight > 0)
  {
    for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
      LandFlyingSeed(mChosenSeeds[i]);
  }

  if (mBoard->mGamepadControls[aPlayerIndex]->mGamepadIndex == -1)
    return 0;

  if (mChooseState == CHOOSE_VIEW_LAWN && theButton == GAMEPAD_BUTTON_A)
  {
    if (CancelLawnView() != 0)
      return RebuildHelpbar();
    return 0;
  }

  const int aCursorX = (aPlayerIndex == 1) ? mCursorPositionX2 : mCursorPositionX1;
  const int aCursorY = (aPlayerIndex == 1) ? mCursorPositionY2 : mCursorPositionY1;
  const int aCursorSeed = (aPlayerIndex == 1) ? mSeedIndex2 : mSeedIndex1;

  switch (theButton)
  {
    case GAMEPAD_BUTTON_UP:
    case GAMEPAD_BUTTON_DPAD_UP:
    case GAMEPAD_BUTTON_DOWN:
    case GAMEPAD_BUTTON_DPAD_DOWN:
    case GAMEPAD_BUTTON_LEFT:
    case GAMEPAD_BUTTON_DPAD_LEFT:
    case GAMEPAD_BUTTON_RIGHT:
    case GAMEPAD_BUTTON_DPAD_RIGHT:
    {
      SeedDir aDirection;
      if (theButton == GAMEPAD_BUTTON_UP || theButton == GAMEPAD_BUTTON_DPAD_UP)
        aDirection = SEED_DIR_UP;
      else if (theButton == GAMEPAD_BUTTON_DOWN || theButton == GAMEPAD_BUTTON_DPAD_DOWN)
        aDirection = SEED_DIR_DOWN;
      else if (theButton == GAMEPAD_BUTTON_LEFT || theButton == GAMEPAD_BUTTON_DPAD_LEFT)
        aDirection = SEED_DIR_LEFT;
      else
        aDirection = SEED_DIR_RIGHT;

      int aSeedIndex = aCursorSeed;

      // Right from the end of a row steps onto the Imitater button.
      if (aDirection == SEED_DIR_RIGHT && aSeedIndex % 8 == 7
          && HasPacket(SEED_IMITATER, false) != 0 && mApp->mGameMode != GAMEMODE_MP_VS)
      {
        aSeedIndex = SEED_IMITATER;
      }
      else
      {
        aSeedIndex = GetNextSeedInDir(aSeedIndex, aDirection);
      }

      if (aPlayerIndex == 1)
      {
        mSeedIndex2 = aSeedIndex;
        return GetSeedPositionInChooser(aSeedIndex, mCursorPositionX2, mCursorPositionY2);
      }
      mSeedIndex1 = aSeedIndex;
      return GetSeedPositionInChooser(aSeedIndex, mCursorPositionX1, mCursorPositionY1);
    }

    case GAMEPAD_BUTTON_SELECT:
    case GAMEPAD_BUTTON_THUMBL:
      // Select peeks at the lawn in survival, where the wave is already running.
      if (mBoard->mCutScene->IsSurvivalRepick() && mChooseState == CHOOSE_NORMAL)
      {
        ButtonDepress(SeedChooserScreen_ViewLawn);
        return 1;
      }
      return 0;

    case GAMEPAD_BUTTON_START:
      if (mShowHelpText && mApp->mGameMode != GAMEMODE_MP_VS)
      {
        ButtonDepress(SeedChooserScreen_Start);
        return 1;
      }
      return 0;

    case GAMEPAD_BUTTON_A:
    {
      if (mApp->mSecondPlayerGamepadIndex == -1 && mPlayerIndex != (int)aPad)
        return 0;

      // A on the Imitater packet opens the copy dialog, or banks it.
      if (aCursorSeed == SEED_IMITATER && mSeedsInBank < mSeedBank1->mNumPackets)
      {
        if (mChosenSeeds[SEED_IMITATER].mSeedState != SEED_IN_BANK)
        {
          ImitaterDialog *aDialog = new ImitaterDialog((int)aPad);
          AddWidget(aDialog);
          aDialog->Resize((800 - aDialog->mWidth) / 2, (600 - aDialog->mHeight) / 2,
                          aDialog->mWidth, aDialog->mHeight);
          mApp->mWidgetManager->SetFocus(aDialog);
          mImitaterDialog = aDialog;
          return 0;
        }
        ClickedSeedInBank(mApp->mSeedChooserScreen->mChosenSeeds[SEED_IMITATER], aPlayerIndex);
      }

      const int aSeedType = SeedHitTest(aCursorX, aCursorY);
      if (aSeedType == SEED_NONE)
        return (aSeedType + 1);

      if (SeedNotAllowedToPick((SeedType)aSeedType) != 0)
      {
        mApp->PlaySample(SOUND_BUZZER, true);
        return 1;
      }

      if (SeedNotAllowedDuringTrial((SeedType)aSeedType) != 0)
      {
        mApp->PlaySample(SOUND_TAP, true);
        if (mApp->LawnMessageBox(51, "[GET_FULL_VERSION_TITLE]", "[GET_FULL_VERSION_BODY]",
                                 "[GET_FULL_VERSION_YES_BUTTON]", "[GET_FULL_VERSION_NO_BUTTON]", 1) != 1000)
          return 1;
        mApp->BuyFullVersion();
        mApp->DoBackToMain();
        return 1;
      }

      ChosenSeedData &aChosenSeed = mChosenSeeds[GetSeedPacketIndex((SeedType)aSeedType)];
      if (aChosenSeed.mSeedState == SEED_IN_BANK)
      {
        if (aChosenSeed.mCrazyDavePicked)
        {
          mApp->PlaySample(SOUND_BUZZER, true);
          ((aPlayerIndex == 1) ? mToolTip2 : mToolTip1)->FlashWarning();
          return 0;
        }
        if (mApp->mGameMode == GAMEMODE_MP_VS)
          return 0;
        return ClickedSeedInBank(aChosenSeed, aPlayerIndex);
      }

      if (aChosenSeed.mSeedState == SEED_IN_CHOOSER)
        return ClickedSeedInChooser(aChosenSeed, aPlayerIndex);
      return 0;
    }

    case GAMEPAD_BUTTON_B:
    {
      if (mChooseState == CHOOSE_VIEW_LAWN)
        return 0;

      // B hands Crazy Dave's free packets back, or offers to quit.
      if (mApp->mGameMode != GAMEMODE_MP_VS)
      {
        int aFreeIndex = 0;
        while (aFreeIndex < NUM_SEEDS_IN_CHOOSER)
        {
          if (!mChosenSeeds[aFreeIndex].mCrazyDavePicked
              && mChosenSeeds[aFreeIndex].mSeedState == SEED_IN_BANK)
            break;
          ++aFreeIndex;
        }

        if (aFreeIndex != NUM_SEEDS_IN_CHOOSER && mSeedsInBank != 0)
        {
          int aTargetIndex;
          if (mApp->IsCoopMode())
          {
            aTargetIndex = 0;
            for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
            {
              if (mChosenSeeds[i].mChosenPlayerIndex == aPlayerIndex
                  && mChosenSeeds[i].mSeedState == SEED_IN_BANK)
                ++aTargetIndex;
            }
          }
          else
          {
            aTargetIndex = mSeedsInBank;
          }
          --aTargetIndex;

          const int aOwnPlayerIndex = mApp->IsCoopMode() ? aPlayerIndex : 0;
          for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
          {
            ChosenSeedData &aChosenSeed = mChosenSeeds[i];
            if (aChosenSeed.mSeedState == SEED_IN_BANK
                && aChosenSeed.mSeedIndexInBank == aTargetIndex
                && !aChosenSeed.mCrazyDavePicked
                && aChosenSeed.mChosenPlayerIndex == aOwnPlayerIndex)
              return ClickedSeedInBank(aChosenSeed, aPlayerIndex);
          }
          return 0;
        }
      }

      Sexy::Dialog *aDialog = mApp->ConfirmQuit();
      mOpeningDialog = true;
      const int aResult = aDialog->WaitForResult(true);
      mOpeningDialog = false;
      if (aResult == 1000)
      {
        mApp->PostLeaveLevel();
        mApp->SetBoardResult(BOARDRESULT_QUIT);
        mApp->DoBackToMain();
      }
      return 0;
    }

    case GAMEPAD_BUTTON_X:
      if (mApp->CanShowStore() != 0 && mApp->mGameMode != GAMEMODE_MP_VS)
      {
        ButtonDepress(SeedChooserScreen_Store);
        return 1;
      }
      return 0;

    case GAMEPAD_BUTTON_Y:
      if (mApp->CanShowAlmanac() != 0 && mApp->mGameMode != GAMEMODE_MP_VS)
      {
        ButtonDepress(SeedChooserScreen_Almanac);
        return 1;
      }
      return 0;

    default:
      return 0;
  }
}

// ==========================================================================
// SeedChooserScreen::Draw(Sexy::Graphics *)
// @0014FB4C  3078 bytes
// ==========================================================================
void SeedChooserScreen::Draw(Sexy::Graphics * g)
{
  // DIALOG_STORE (6) and DIALOG_ALMANAC (5) cover the whole screen, so nothing
  // of the chooser may be drawn underneath them.
  if (mApp->GetDialog(6) != nullptr || mApp->GetDialog(5) != nullptr)
    return;

  g->SetLinearBlend(true);

  if (!mBoard->ChooseSeedsOnCurrentLevel())
    return;
  if (mBoard->mCutScene != nullptr && mBoard->mCutScene->IsBeforePreloading())
    return;

  // Every packet on this screen is tinted with this colour; VS fades it while
  // the opponent is still choosing.
  Sexy::Color aBaseColor(255, 255, 255);

  if (mApp->mGameMode == GAMEMODE_MP_VS && !CanPickNow())
  {
    const float aDimAmount = TodAnimateCurveFloat(0, 25, mDimCounter, 1.0f, 0.45f, CURVE_EASE_IN_OUT);
    g->SetColorizeImages(true);
    aBaseColor = Sexy::Color((int)(aDimAmount * 255.0f), (int)(aDimAmount * 255.0f), (int)(aDimAmount * 255.0f));
    g->SetColor(aBaseColor);
  }

  Sexy::Image *aBackgroundImage = mIsZombieChooser
      ? IMAGE_SEEDCHOOSER_BACKGROUND2
      : IMAGE_SEEDCHOOSER_BACKGROUND;
  g->DrawImage(aBackgroundImage, 0, 87);

  // The Imitater add-on belongs to the plant chooser only, and VS has no room
  // for it.
  if (!mIsZombieChooser && HasPacket(SEED_IMITATER, false) && mApp->mGameMode != GAMEMODE_MP_VS)
  {
    g->DrawImage(IMAGE_SEEDCHOOSER_IMITATERADDON,
        mImitaterButton->mX - 5, mImitaterButton->mY - 12);
  }

  Sexy::Color aTitleColor;
  Sexy::String aTitleText;
  if (mIsZombieChooser)
  {
    aTitleColor = Sexy::Color(0, 255, 0);
    aTitleText = "[CHOOSE_YOUR_ZOMBIES]";
  }
  else
  {
    aTitleColor = Sexy::Color(213, 159, 43);
    aTitleText = "[CHOOSE_YOUR_PLANTS]";
  }
  TodDrawString(g, aTitleText, aBackgroundImage->mWidth / 2, 114,
      FONT_DWARVENTODCRAFT18, aTitleColor, 2);

  // How many packets the chooser shows on this level.
  int aNumSeeds = 19;
  if (!mIsZombieChooser)
  {
    if (mApp->mGameMode == GAMEMODE_MP_VS || !Has7Rows())
      aNumSeeds = 40;
    else if (HasPacket(SEED_IMITATER, false))
      aNumSeeds = 49;
    else
      aNumSeeds = 48;
  }

  // The packets are drawn in two passes: the first draws the packet itself (and
  // the silhouettes of the slots that hold nothing), the second stamps the
  // packet's shadow on top. Both passes also record where each player's cursor
  // is resting.
  int aCursorSeed1 = -1;
  int aCursorAlpha1 = 255;
  int aCursorSeed2 = -1;
  int aCursorAlpha2 = 255;

  for (int aPass = 0; aPass < 2; ++aPass)
  {
    const bool aFirstPass = (aPass == 0);
    const bool aDrawShadow = (aPass == 1);

    for (int aSeedIndex = 0; aSeedIndex < aNumSeeds; ++aSeedIndex)
    {
      int aSeedX = 0;
      int aSeedY = 0;
      GetSeedPositionInChooser(aSeedIndex, aSeedX, aSeedY);

      const int aDisplaySeedType = mIsZombieChooser ? GetZombieSeedType(aSeedIndex) : aSeedIndex;
      if (aDisplaySeedType == SEED_IMITATER)
        continue;

      if (aDisplaySeedType == SEED_NONE || !HasPacket(aDisplaySeedType, mIsZombieChooser))
      {
        // Nothing is drawn here, so the first pass leaves an empty silhouette.
        if (aFirstPass)
          g->DrawImage(IMAGE_SEEDPACKETSILHOUETTE, aSeedX, aSeedY);
        continue;
      }

      // Packets still sitting in the chooser are drawn by the loop below.
      if (mChosenSeeds[aSeedIndex].mSeedState == SEED_IN_CHOOSER)
        continue;

      if (mSeedIndex1 == aSeedIndex)
      {
        aCursorSeed1 = aSeedIndex;
        aCursorAlpha1 = 55;
      }
      if (mSeedIndex2 == aSeedIndex)
      {
        aCursorSeed2 = aSeedIndex;
        aCursorAlpha2 = 55;
      }

      DrawPacket(g, aSeedX, aSeedY, aDisplaySeedType, SEED_NONE, 0.0f, 55, aBaseColor,
          aDrawShadow, aFirstPass);
    }
  }

  // Empty bank slots get a silhouette so the player can see the shape of the
  // bank before anything is put in it.
  const int aNumSeedsInBank = mSeedBank1->mNumPackets;
  for (int aBankIndex = 0; aBankIndex < aNumSeedsInBank; ++aBankIndex)
  {
    if (FindSeedInBank(aBankIndex, mIsZombieChooser) != SEED_NONE)
      continue;

    int aBankX = 0;
    int aBankY = 0;
    GetSeedPositionInBank(aBankIndex, aBankX, aBankY, 0);
    g->DrawImage(IMAGE_SEEDPACKETSILHOUETTE, aBankX, aBankY);
  }

  // Co-op has a second bank, and its empty slots are silhouetted as well.
  if (mApp->IsCoopMode() && mSeedBank2 != nullptr && aNumSeedsInBank > 0)
  {
    for (int aBankIndex = 0; aBankIndex < aNumSeedsInBank; ++aBankIndex)
    {
      if (FindSeedInBank(aBankIndex, 1) != SEED_NONE)
        continue;

      int aBankX = 0;
      int aBankY = 0;
      GetSeedPositionInBank(aBankIndex, aBankX, aBankY, 1);
      g->DrawImage(IMAGE_SEEDPACKETSILHOUETTE, aBankX, aBankY);
    }
  }

  // Packets that have left the chooser -- sitting in a bank slot or in flight --
  // are drawn at their own animated position, in the same two passes.
  for (int aPass = 0; aPass < 2; ++aPass)
  {
    const bool aFirstPass = (aPass == 0);
    const bool aDrawShadow = (aPass == 1);

    for (int aSeedIndex = 0; aSeedIndex < 49; ++aSeedIndex)
    {
      const bool aIsZombie = mIsZombieChooser;
      const int aDisplaySeedType = aIsZombie ? GetZombieSeedType(aSeedIndex) : aSeedIndex;
      if (!HasPacket(aDisplaySeedType, aIsZombie))
        continue;
      if (aDisplaySeedType == SEED_NONE || aSeedIndex >= aNumSeeds)
        continue;

      ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedIndex];
      const ChosenSeedState aSeedState = aChosenSeed.mSeedState;

      // Only a packet in a bank slot, or one still in the chooser while the cut
      // scene lets the player choose, is visible at all.
      if (aSeedState != SEED_IN_BANK && aSeedState != SEED_IN_CHOOSER)
        continue;
      if (aSeedState != SEED_IN_CHOOSER && !mBoard->mCutScene->mSeedChoosing)
        continue;

      int aPacketX = aChosenSeed.mX;
      int aPacketY = aChosenSeed.mY;

      // A packet this level will not let the player use is greyed out.
      bool aGrayed = false;
      if (!aIsZombie)
      {
        // TODO(recon): the binary passes only the receiver to SeedNotRecommendedToPick, so the seed type it tests is unrecoverable.
        const unsigned int aRecommendFlags = SeedNotRecommendedToPick(aChosenSeed.mSeedType);
        if ((aRecommendFlags != 0 && aSeedState == SEED_IN_CHOOSER)
            || (SeedNotAllowedToPick(aChosenSeed.mSeedType) != 0 && aSeedState == SEED_IN_CHOOSER))
        {
          aGrayed = true;
        }
        if (SeedNotAllowedDuringTrial(aChosenSeed.mSeedType) != 0)
          aGrayed = true;
      }
      const int aGrayness = aGrayed ? 115 : 255;

      // A packet in the bank sits at its bank slot; the stored position is kept
      // in step so that a later flight starts from the right place.
      if (aSeedState == SEED_IN_BANK)
      {
        GetSeedPositionInBank(aChosenSeed.mSeedIndexInBank, aPacketX, aPacketY,
            aChosenSeed.mChosenPlayerIndex);
        aChosenSeed.mX = aPacketX;
        aChosenSeed.mY = aPacketY;
      }

      // Remember where each player's cursor is resting, so the packet it holds
      // can be drawn on top of the others further down.
      if (mSeedIndex1 == aSeedIndex && mBoard->mGamepadControls[0]->mGamepadIndex != -1
          && aSeedState == SEED_IN_CHOOSER)
      {
        aCursorSeed1 = aSeedIndex;
        aCursorAlpha1 = aGrayness;
      }
      if (mSeedIndex2 == aSeedIndex && mBoard->mGamepadControls[1]->mGamepadIndex != -1
          && aSeedState == SEED_IN_CHOOSER)
      {
        aCursorSeed2 = aSeedIndex;
        aCursorAlpha2 = aGrayness;
      }

      DrawPacket(g, aPacketX, aPacketY, aChosenSeed.mSeedType, aChosenSeed.mImitaterType,
          0.0f, aGrayness, aBaseColor, aDrawShadow, aFirstPass);
    }
  }

  // The Imitater button only exists for the plant chooser, and VS hides it.
  // Its animated position is the pair of floats the slide-in animator writes
  // into GameButton::mAnchorX and mAnchorY.
  if (!mIsZombieChooser && mApp->mGameMode != GAMEMODE_MP_VS)
  {
    const int aButtonX = (int)mImitaterButton->mAnchorX;
    const int aButtonY = (int)mImitaterButton->mAnchorY;
    g->Translate(aButtonX, aButtonY);
    mImitaterButton->Draw(g);
    g->Translate(-aButtonX, -aButtonY);
  }

  // A selector frame marks the packet each player's gamepad cursor is on.
  for (int aPlayerIndex = 0; aPlayerIndex < 2; ++aPlayerIndex)
  {
    const int aGamepadIndex = mBoard->mGamepadControls[aPlayerIndex]->mGamepadIndex;
    if (aGamepadIndex == -1 || mSelectedButton != nullptr)
      continue;
    if (aGamepadIndex != mPlayerIndex && mApp->mGameMode == GAMEMODE_MP_VS)
      continue;

    const int aCursorX = (aPlayerIndex != 0) ? mCursorPositionX2 : mCursorPositionX1;
    const int aCursorY = (aPlayerIndex != 0) ? mCursorPositionY2 : mCursorPositionY1;
    Sexy::Image *aSelectorImage = (aGamepadIndex == mApp->mSecondPlayerGamepadIndex)
        ? IMAGE_SEED_SELECTOR_BLUE
        : IMAGE_SEED_SELECTOR;
    g->DrawImage(aSelectorImage, aCursorX - 8, aCursorY - 4, 64, 85);
  }

  // The packet under each player's cursor is redrawn on top, a little lower, so
  // that it looks lifted out of the chooser.
  if (aCursorSeed1 != -1 && ShouldDisplayCursor(0) != 0)
  {
    int aCursorX = 0;
    int aCursorY = 0;
    GetSeedPositionInChooser(aCursorSeed1, aCursorX, aCursorY);
    const int aDisplaySeedType = mIsZombieChooser ? GetZombieSeedType(aCursorSeed1) : aCursorSeed1;
    DrawPacket(g, aCursorX, aCursorY + 5, aDisplaySeedType, SEED_NONE, 0.0f, aCursorAlpha1,
        aBaseColor, true, true);
  }
  if (aCursorSeed2 != -1 && ShouldDisplayCursor(1) != 0)
  {
    int aCursorX = 0;
    int aCursorY = 0;
    GetSeedPositionInChooser(aCursorSeed2, aCursorX, aCursorY);
    const int aDisplaySeedType = mIsZombieChooser ? GetZombieSeedType(aCursorSeed2) : aCursorSeed2;
    DrawPacket(g, aCursorX, aCursorY + 5, aDisplaySeedType, SEED_NONE, 0.0f, aCursorAlpha2,
        aBaseColor, true, true);
  }

  // Each player's cursor is an arrow that bobs up and down on a sine wave.
  for (int aPlayerIndex = 0; aPlayerIndex < 2; ++aPlayerIndex)
  {
    if (ShouldDisplayCursor(aPlayerIndex) == 0
        || mBoard->mGamepadControls[aPlayerIndex]->mGamepadIndex == -1)
    {
      continue;
    }

    Sexy::Image *aArrowImage = (aPlayerIndex != 0)
        ? IMAGE_CURSOR_ARROW_P2
        : IMAGE_CURSOR_ARROW_P1;
    Sexy::Image *aTextImage = (aPlayerIndex != 0)
        ? IMAGE_CURSOR_P2_TEXT
        : IMAGE_CURSOR_P1_TEXT;
    const int aCursorX = (aPlayerIndex != 0) ? mCursorPositionX2 : mCursorPositionX1;
    const int aCursorY = (aPlayerIndex != 0) ? mCursorPositionY2 : mCursorPositionY1;
    const float aBounce = sinf(mCursorBobPhase * 5.0f) * 2.0f;

    g->DrawImageF(aArrowImage, (float)(aCursorX + 25 - aArrowImage->mWidth / 2),
        (float)(aCursorY - 8) + aBounce);
    g->DrawImageF(aTextImage, (float)(aCursorX + 25 - aTextImage->mWidth / 2),
        (float)(aCursorY - 32));
  }

  // Packets in flight between the chooser and a bank are drawn undimmed.
  for (int aSeedIndex = 0; aSeedIndex < 49; ++aSeedIndex)
  {
    if (!HasPacket(aSeedIndex, mIsZombieChooser))
      continue;

    const ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedIndex];
    if (aChosenSeed.mSeedState != SEED_FLYING_TO_BANK
        && aChosenSeed.mSeedState != SEED_FLYING_TO_CHOOSER)
    {
      continue;
    }

    DrawPacket(g, aChosenSeed.mX, aChosenSeed.mY, aChosenSeed.mSeedType,
        aChosenSeed.mImitaterType, 0.0f, 255, aBaseColor, true, true);
  }

  // Without a gamepad the four buttons are drawn here; with one they are drawn
  // by the gamepad cursor path instead, and the help line takes their place.
  if (!mApp->HasGamepad() && (!mApp->mGamePad1IsOn || !mApp->mGamePad2IsOn))
  {
    const int aNumButtons = (int)mButtons.size();
    for (int aButtonIndex = 0; aButtonIndex < aNumButtons; ++aButtonIndex)
    {
      GameButton *aButton = mButtons[aButtonIndex];
      if (!aButton->mVisible)
        continue;

      const int aButtonX = (int)aButton->mAnchorX;
      const int aButtonY = (int)aButton->mAnchorY;
      g->Translate(aButtonX, aButtonY);
      aButton->Draw(g);
      g->Translate(-aButtonX, -aButtonY);
    }

    DeferOverlay(0);
    return;
  }

  if (mShowHelpText && mApp->mGameMode != GAMEMODE_MP_VS)
  {
    // The help line flashes: grey for the first half of every hundred frames,
    // white for the second. The binary offsets the line by +63 rather than the
    // -63 the PC source uses, and that is what is reproduced here.
    const int aFlashPhase = mSeedChooserAge % 100;
    Sexy::String aHelpText("[HELP_TEXT_2_START]");
    const int aTextX = aBackgroundImage->mWidth / 2;
    const int aTextY = aBackgroundImage->mHeight + 63;
    const Sexy::Color aTextColor = (aFlashPhase <= 50)
        ? Sexy::Color(127, 127, 127, 255)
        : Sexy::Color::White;

    TodDrawString(g, aHelpText, aTextX, aTextY, FONT_DWARVENTODCRAFT24,
        aTextColor, 2);
    DeferOverlay(0);
    return;
  }

  // If the second player's gamepad has dropped out mid-pick, blink a warning at
  // them. The counter is global, so the blink runs on across frames.
  const int aSecondGamepadIndex = mApp->mSecondPlayerGamepadIndex;
  if (aSecondGamepadIndex != -1 && aSecondGamepadIndex == mPlayerIndex
      && mApp->mGamepads[aSecondGamepadIndex]->mStatus == Sexy::Gamepad::STATUS_DISCONNECTED)
  {
    ++gSeedChooserWarnTick;
    if (gSeedChooserWarnTick % 60 > 30)
    {
      Sexy::String aFormat;
      TodStringTranslate(&aFormat, "[RECONNECT_SECOND_CONTROLLER_FMT]");
      Sexy::String aWarningText;
      StrFormat(&aWarningText, aFormat.c_str(), 2);

      const Sexy::Color aWarningColor(255, 0, 0);
      TodDrawString(g, aWarningText, aBackgroundImage->mWidth / 2,
          aBackgroundImage->mHeight + 63, FONT_DWARVENTODCRAFT18,
          aWarningColor, 2);
    }
  }

  DeferOverlay(0);
}

// ==========================================================================
// SeedChooserScreen::SeedChooserScreen(bool)
// @001509EC  2068 bytes
// ==========================================================================
SeedChooserScreen::SeedChooserScreen(bool theIsZombieChooser)
{
  // Sexy::Widget's constructor has already run and written both vptrs -- the
  // primary one at +0x00 and the ButtonListener one at +0x100 -- and mButtons is
  // a real member, so it was default constructed too. Neither is repeated here.
  mApp = (LawnApp *)gSexyAppBase;
  mClip = false;
  mBoard = mApp->mBoard;
  mSeedsInFlight = 0;
  mSeedsInBank = 0;
  mSeedsIn1PBank = 0;
  mSeedsIn2PBank = 0;
  mSeedIndex1 = 0;
  mSeedIndex2 = 0;
  mCursorPositionX1 = -1;
  mCursorPositionX2 = -1;
  mCursorPositionY1 = -1;
  mCursorPositionY2 = -1;
  GetSeedPositionInChooser(0, mCursorPositionX1, mCursorPositionY1);
  GetSeedPositionInChooser(mSeedIndex2, mCursorPositionX2, mCursorPositionY2);
  mChooseState = CHOOSE_NORMAL;
  mViewLawnTime = 0;

  mToolTip1 = new ToolTipWidget();
  mToolTip2 = new ToolTipWidget();

  mIsZombieChooser = theIsZombieChooser;
  mToolTipSeed1 = -1;
  mToolTipSeed2 = -1;
  mImitaterDialog = nullptr;

  if (mIsZombieChooser)
  {
    // The zombie chooser borrows the almanac's art for its packet pictures.
    Sexy::String aAlmanacResources("DelayLoad_Almanac");
    TodLoadResources(aAlmanacResources);
    mSeedBank1 = mBoard->mSeedBank[1];
    mPlayerIndex = -1;
  }
  else
  {
    mSeedBank1 = mBoard->mSeedBank[0];
    mPlayerIndex = mApp->mPlayerInfo->GetId();
  }

  // Only co-op has a second bank. The binary leaves this member untouched
  // outside co-op mode; zeroing it first keeps it defined in every mode.
  mSeedBank2 = nullptr;
  if (mApp->IsCoopMode())
    mSeedBank2 = mBoard->mSeedBank[1];

  mShowHelpText = false;

  mImitaterButton = new GameButton(SeedChooserScreen_Imitater, nullptr);
  mImitaterButton->mButtonImage = IMAGE_IMITATERSEED;
  mImitaterButton->mOverImage = IMAGE_IMITATERSEED;
  mImitaterButton->mDownImage = IMAGE_IMITATERSEED;
  mImitaterButton->mDisabledImage = IMAGE_IMITATERSEEDDISABLED;
  mImitaterButton->Resize(464, 490,
      (IMAGE_IMITATERSEED)->mWidth,
      (IMAGE_IMITATERSEED)->mHeight);
  mImitaterButton->mParentWidget = this;

  // The view-lawn button only exists when a survival level offers a repick.
  if (mBoard->mCutScene->IsSurvivalRepick() && mChooseState == CHOOSE_NORMAL)
  {
    Sexy::String aViewLawnLabel("[VIEW_LAWN]");
    mViewLawnButton = (GameButton *)MakeButton(SeedChooserScreen_ViewLawn,
        static_cast<Sexy::ButtonListener *>(this), this, aViewLawnLabel);
    mViewLawnButton->mParentWidget = this;
    mButtons.push_back(mViewLawnButton);
  }
  else
  {
    mViewLawnButton = nullptr;
  }

  Sexy::String aStoreLabel("[SHOP_BUTTON]");
  mStoreButton = (GameButton *)MakeButton(SeedChooserScreen_Store,
      static_cast<Sexy::ButtonListener *>(this), this, aStoreLabel);
  mStoreButton->mParentWidget = this;
  mButtons.push_back(mStoreButton);

  Sexy::String aStartLabel("[LETS_ROCK_BUTTON]");
  mStartButton = (GameButton *)MakeButton(SeedChooserScreen_Start,
      static_cast<Sexy::ButtonListener *>(this), this, aStartLabel);
  mStartButton->mParentWidget = this;
  mButtons.push_back(mStartButton);

  Sexy::String aAlmanacLabel("[ALMANAC_BUTTON]");
  mAlmanacButton = (GameButton *)MakeButton(SeedChooserScreen_Almanac,
      static_cast<Sexy::ButtonListener *>(this), this, aAlmanacLabel);
  mAlmanacButton->mParentWidget = this;
  mButtons.push_back(mAlmanacButton);

  mSelectedButton = nullptr;

  // Size every button to its own label, then spread them evenly along the
  // bottom of the chooser.
  const int aNumButtons = (int)mButtons.size();
  if (aNumButtons != 0)
  {
    std::vector<int> aButtonWidths;
    aButtonWidths.resize(aNumButtons, 0);

    int aTotalWidth = 0;
    for (int aButtonIndex = 0; aButtonIndex < aNumButtons; ++aButtonIndex)
    {
      GameButton *aButton = mButtons[aButtonIndex];
      const int aLabelWidth = (FONT_DWARVENTODCRAFT18)->StringWidth(aButton->mLabel);
      const int aLeftWidth = (IMAGE_BUTTON_LEFT)->mWidth;
      const int aMiddleWidth = (IMAGE_BUTTON_MIDDLE)->mWidth;
      const int aRightWidth = (IMAGE_BUTTON_RIGHT)->mWidth;
      // A long label stretches the middle slice; a short one only gets a single
      // slice of it, which is what the "minimum" flag below selects.
      const int aStretchWidth = aLabelWidth - aLeftWidth - aRightWidth;
      const int aMinimumMiddle = (aLabelWidth > 3 * aLeftWidth / 2) ? 1 : 0;
      const int aContentWidth = (aMinimumMiddle < aStretchWidth)
          ? (aMiddleWidth + aStretchWidth)
          : (aMiddleWidth + aMinimumMiddle);
      const int aButtonWidth = aLeftWidth + aRightWidth + aMiddleWidth * ((aContentWidth - 1) / aMiddleWidth);
      aButtonWidths[aButtonIndex] = aButtonWidth;
      aTotalWidth += aButtonWidth;
    }

    const int aGap = ((IMAGE_SEEDCHOOSER_BACKGROUND)->mWidth - 23 - aTotalWidth) / (aNumButtons + 1);
    int aButtonX = aGap + 10;
    for (int aButtonIndex = 0; aButtonIndex < aNumButtons; ++aButtonIndex)
    {
      GameButton *aButton = mButtons[aButtonIndex];
      aButton->Resize(aButtonX, 548, aButtonWidths[aButtonIndex] + 1, aButton->mHeight);
      aButtonX += aButtonWidths[aButtonIndex] + aGap;
    }
  }

  EnableStartButton(false);
  if (mViewLawnButton != nullptr)
  {
    // The button is dead unless this really is a survival repick taken from the
    // normal chooser.
    if (!mBoard->mCutScene->IsSurvivalRepick() || mChooseState != CHOOSE_NORMAL)
      mViewLawnButton->SetDisabled(true);
    else
      mViewLawnButton->SetDisabled(false);
  }

  // Every chooser slot starts empty, holding a packet that sits in the chooser.
  memset(mChosenSeeds, 0, sizeof(mChosenSeeds));
  for (int aSeedIndex = 0; aSeedIndex < 49; ++aSeedIndex)
  {
    ChosenSeedData &aChosenSeed = mChosenSeeds[aSeedIndex];
    aChosenSeed.mSeedType = (SeedType)(mIsZombieChooser ? GetZombieSeedType(aSeedIndex) : aSeedIndex);
    GetSeedPositionInChooser(aSeedIndex, aChosenSeed.mX, aChosenSeed.mY);
    aChosenSeed.mTimeStartMotion = 0;
    aChosenSeed.mTimeEndMotion = 0;
    aChosenSeed.mStartX = aChosenSeed.mX;
    aChosenSeed.mStartY = aChosenSeed.mY;
    aChosenSeed.mEndX = aChosenSeed.mX;
    aChosenSeed.mEndY = aChosenSeed.mY;
    aChosenSeed.mChosenPlayerIndex = 0;
    aChosenSeed.mSeedState = SEED_IN_CHOOSER;
    aChosenSeed.mSeedIndexInBank = -1;
    aChosenSeed.mRefreshing = false;
    aChosenSeed.mRefreshCounter = 0;
    aChosenSeed.mImitaterType = SEED_NONE;
    aChosenSeed.mCrazyDavePicked = false;
  }
  // The Imitater is not a packet of its own: it stays hidden until it is picked.
  mChosenSeeds[SEED_IMITATER].mSeedState = SEED_PACKET_HIDDEN;

  if (mBoard->mCutScene->IsSurvivalRepick())
  {
    // A repick keeps the recharge timers the previous bank had run down to.
    for (int aPacketIndex = 0; aPacketIndex < mSeedBank1->mNumPackets; ++aPacketIndex)
    {
      const SeedPacket &aPacket = mSeedBank1->mSeedPackets[aPacketIndex];
      mChosenSeeds[aPacket.mPacketType].mRefreshing = aPacket.mRefreshing;
      mChosenSeeds[aPacket.mPacketType].mRefreshCounter = aPacket.mRefreshCounter;
    }
    mSeedBank1->mNumPackets = 0;

    if (mBoard->mApp->IsCoopMode())
    {
      for (int aPacketIndex = 0; aPacketIndex < mSeedBank2->mNumPackets; ++aPacketIndex)
      {
        const SeedPacket &aPacket = mSeedBank2->mSeedPackets[aPacketIndex];
        mChosenSeeds[aPacket.mPacketType].mRefreshing = aPacket.mRefreshing;
        mChosenSeeds[aPacket.mPacketType].mRefreshCounter = aPacket.mRefreshCounter;
        mChosenSeeds[aPacket.mPacketType].mChosenPlayerIndex = 1;
      }
      mSeedBank2->mNumPackets = 0;
    }
  }

  if (mApp->mGameMode == GAMEMODE_CHALLENGE_SEEING_STARS)
  {
    // Seeing Stars starts the player off with a free Starfruit in the bank.
    const int aStarfruitX = mBoard->GetSeedPacketPositionX(0, 0, false);
    ChosenSeedData &aStarfruit = mChosenSeeds[SEED_STARFRUIT];
    aStarfruit.mX = aStarfruitX;
    aStarfruit.mY = 8;
    aStarfruit.mStartX = aStarfruitX;
    aStarfruit.mStartY = 8;
    aStarfruit.mEndX = aStarfruitX;
    aStarfruit.mEndY = 8;
    ++mSeedsInBank;
    ++mSeedsIn1PBank;
    aStarfruit.mSeedState = SEED_IN_BANK;
    aStarfruit.mSeedIndexInBank = 0;
  }

  // A level that ships its own seed list fills the bank from it; otherwise
  // Crazy Dave picks for the player on any adventure replay.
  if (mBoard->IsLevelDataLoaded() && mApp->mLevel.mSeedConfig.size() > 0)
    PickSeedsFromLevelConfig();
  else if (mApp->IsAdventureMode() && !mApp->IsFirstTimeAdventureMode())
    CrazyDavePickSeeds();

  UpdateImitaterButton();
  mCursorBobPhase = 0.0f;
  mDimCounter = 0;
  mOpeningDialog = false;
  mSeedChooserAge = 0;
}

// ==========================================================================
// SeedChooserScreen::Update()
void SeedChooserScreen::Update()
{
  Sexy::Widget::Update();
  ++mSeedChooserAge;

  // The dim overlay only fades in while the chooser is not accepting picks.
  mDimCounter = CanPickNow() ? 0 : (mDimCounter + 1);
  mCursorBobPhase = (mCursorBobPhase + 0.01f <= 6.2832f) ? (mCursorBobPhase + 0.01f) : 0.0f;

  mToolTip1->Update();
  mToolTip2->Update();

  for (int i = 0; i < NUM_SEEDS_IN_CHOOSER; ++i)
  {
    if (HasPacket(i, mIsZombieChooser) == 0)
      continue;

    ChosenSeedData &aChosenSeed = mChosenSeeds[i];
    if (aChosenSeed.mSeedState != SEED_FLYING_TO_BANK
        && aChosenSeed.mSeedState != SEED_FLYING_TO_CHOOSER)
      continue;

    aChosenSeed.mX = TodAnimateCurve(aChosenSeed.mTimeStartMotion, aChosenSeed.mTimeEndMotion,
                                     mSeedChooserAge, aChosenSeed.mStartX,
                                     (float)aChosenSeed.mEndX, CURVE_EASE_IN_OUT);
    aChosenSeed.mY = TodAnimateCurve(aChosenSeed.mTimeStartMotion, aChosenSeed.mTimeEndMotion,
                                     mSeedChooserAge, aChosenSeed.mStartY,
                                     (float)aChosenSeed.mEndY, CURVE_EASE_IN_OUT);

    if (mSeedChooserAge >= aChosenSeed.mTimeEndMotion)
      LandFlyingSeed(aChosenSeed);
  }

  const int aPlayerIndex = mApp->GamepadToPlayerIndex(mPlayerIndex);
  ShowToolTip(aPlayerIndex);
  if (mApp->IsCoopMode() || (mApp->IsAdventureMode() && mApp->mSecondPlayerGamepadIndex != -1))
    ShowToolTip(aPlayerIndex == 0);

  mImitaterButton->Update();

  // A gamepad appearing or leaving drops the button cursor back to the grid.
  if (mSelectedButton != nullptr
      && (mApp->HasGamepad() || (mApp->mGamePad1IsOn && mApp->mGamePad2IsOn)))
  {
    GameButton *aSlotButton = mSelectedButton;
    aSlotButton->mIsDown = false;
    aSlotButton->mIsOver = false;
    mSelectedButton = nullptr;
  }

  for (int i = 0; i < (int)mButtons.size(); ++i)
    mButtons[i]->Update();

  UpdateViewLawn();
  MarkDirty();
}

// ==========================================================================
// SeedChooserScreen::GotFocus()
// @00151658  24 bytes
// ==========================================================================
void SeedChooserScreen::GotFocus()
{
  if (mChooseState == CHOOSE_NORMAL)
    RebuildHelpbar();
  Sexy::Widget::GotFocus();
}

