{
  Sexy::WidgetContainer::AddedToManager(theManager);
}

// ==========================================================================
// SeedChooserScreen::~SeedChooserScreen()
// @0014BCB0  436 bytes
// ==========================================================================
SeedChooserScreen::~SeedChooserScreen()
{
  // The two vptr stores are the compiler's and the trailing
  // `Sexy::Widget::~Widget(this)` is the base, which C++ runs.
  //
  // The word at +0xEF4 is mImitaterDialog: the screen takes it off the manager
  // and deletes it, because the dialog outlives nothing here.
  if ( mImitaterDialog != nullptr )
  {
    Sexy::WidgetContainer::RemoveWidget(mImitaterDialog);
    mApp->SafeDeleteWidget(mImitaterDialog);
  }

  // The vector at +0xF08 is mButtons (the almanac/store/start/view-lawn
  // buttons). Each one is deleted here. The vector frees its own storage.
  for ( size_t i = 0; i < mButtons.size(); ++i )
    delete mButtons[i];

  // The word at +0x108 is mImitaterButton.
  delete mImitaterButton;

  // The two words at +0xEA8 and +0xEAC are the two tooltips; each is released
  // the same way ChallengeScreen releases its own, i.e. `delete`.
  delete mToolTip1;
  delete mToolTip2;

  // The byte at +0xEE4 is mIsZombieChooser, and the resources group below is
  // the one the constructor only loads in that mode.
  if ( mIsZombieChooser )
  {
    Sexy::String aAlmanacResources("DelayLoad_Almanac");
    TodDeleteResources(aAlmanacResources);
  }

}
